function cx_log(msg)
    if Logger and Logger.LogInfo then
        Logger.LogInfo(tostring(msg))
    else
        print(tostring(msg))
    end
end


meow_category_searches = {}
meow_category_search_render = {}

meow_search_key_codes = {
    MOUSE1 = 1, MOUSE2 = 2, MOUSE3 = 4, MOUSE4 = 5, MOUSE5 = 6,
    LMB = 1, RMB = 2, MMB = 4,
    BACKSPACE = 8, TAB = 9, ENTER = 13, SHIFT = 16, CTRL = 17,
    ALT = 18, ESC = 27, SPACE = 32, PAGEUP = 33, PAGEDOWN = 34,
    HOME = 36, LEFT = 37, UP = 38, RIGHT = 39, DOWN = 40,
    INSERT = 45, DELETE = 46,
    [";"] = 186, ["="] = 187, [","] = 188, ["-"] = 189,
    ["."] = 190, ["/"] = 191, ["`"] = 192, ["["] = 219,
    ["\\"] = 220, ["]"] = 221, ["'"] = 222,
}

function meow_search_key_code(value)
    local text = tostring(value or ""):upper():gsub("^%s+", ""):gsub("%s+$", "")
    local numeric = tonumber(text)
    if numeric and numeric >= 1 and numeric <= 255 then return math.floor(numeric) end
    local f_number = tonumber(text:match("^F(%d+)$"))
    if f_number and f_number >= 1 and f_number <= 24 then return 111 + f_number end
    if #text == 1 and text:match("[%w]") then return string.byte(text) end
    return meow_search_key_codes[text]
end

function meow_category_search(tab, key, path)
    if not tab or meow_category_searches[key] then return end

    local state = { matches = {}, path = tostring(path or "") }
    meow_category_searches[key] = state
    meow_category_search_render[cherax_main_category(path) .. "|" .. cherax_sub_tab(path)] = state

    state.input_hash = feature_hash("Category Search Input", key)
    state.list_hash = feature_hash("Category Search Results", key)
    state.search_hash = feature_hash("Category Search Button", key)
    state.play_hash = feature_hash("Category Search Play", key)
    state.clear_hash = feature_hash("Category Search Clear", key)
    state.hotkey_input_hash = feature_hash("Category Search Hotkey Input", key)
    state.hotkey_add_hash = feature_hash("Category Search Hotkey Add", key)
    state.hotkey_clear_hash = feature_hash("Category Search Hotkey Clear", key)

    FeatureMgr.RemoveFeature(state.input_hash)
    FeatureMgr.RemoveFeature(state.list_hash)
    FeatureMgr.RemoveFeature(state.search_hash)
    FeatureMgr.RemoveFeature(state.play_hash)
    FeatureMgr.RemoveFeature(state.clear_hash)
    FeatureMgr.RemoveFeature(state.hotkey_input_hash)
    FeatureMgr.RemoveFeature(state.hotkey_add_hash)
    FeatureMgr.RemoveFeature(state.hotkey_clear_hash)

    state.input = FeatureMgr.AddFeature(
        state.input_hash,
        "Search animations",
        eFeatureType.InputText,
        "Type part of an animation name"
    )

    state.results = FeatureMgr.AddFeature(
        state.list_hash,
        "Search results",
        eFeatureType.Combo,
        "Matching animations in this category"
    )

    state.results:SetList({ "Type a name and press Search" })
    state.results:SetListIndex(0)

    state.search = FeatureMgr.AddFeature(
        state.search_hash,
        "Search",
        eFeatureType.Button,
        "Search animations in this category",
        function()
            local query = tostring(state.input:GetStringValue() or "")
                :lower():gsub("^%s+", ""):gsub("%s+$", "")
            local names = {}
            state.matches = {}

            if query ~= "" then
                local prefix = state.path .. " / "
                for _, entry in ipairs(cherax_ui_entries) do
                    local label = tostring(entry.label or "")
                    local name = tostring(entry.name or "")
                    if entry.callback
                    and label:sub(1, #prefix) == prefix
                    and not label:find("[toggle]", 1, true)
                    and (name .. " " .. label):lower():find(query, 1, true) then
                        state.matches[#state.matches + 1] = entry
                    end
                end

                table.sort(state.matches, function(a, b)
                    return tostring(a.name):lower() < tostring(b.name):lower()
                end)

                for _, entry in ipairs(state.matches) do
                    names[#names + 1] = tostring(entry.name or "Animation")
                end
            end

            if #names == 0 then names[1] = "No matching animations" end
            state.results:SetList(names)
            state.results:SetListIndex(0)
        end,
        true
    )

    state.play = FeatureMgr.AddFeature(
        state.play_hash,
        "Play selected result",
        eFeatureType.Button,
        "Play the selected animation",
        function()
            local index = state.results:GetListIndex() + 1
            local selected = state.matches[index]
            if selected and selected.callback then
                Script.QueueJob(selected.callback)
            else
                safe_notify("Animation Search", "Select a matching animation first")
            end
        end,
        true
    )

    state.clear = FeatureMgr.AddFeature(
        state.clear_hash,
        "Clear search",
        eFeatureType.Button,
        "Clear the text and results",
        function()
            state.input:SetStringValue("")
            state.matches = {}
            state.results:SetList({ "Type a name and press Search" })
            state.results:SetListIndex(0)
        end,
        true
    )

    state.hotkey_input = FeatureMgr.AddFeature(
        state.hotkey_input_hash,
        "Hotkey key",
        eFeatureType.InputText,
        "Letter, F1-F24, MOUSE1-MOUSE5, or virtual-key code"
    )

    state.hotkey_add = FeatureMgr.AddFeature(
        state.hotkey_add_hash,
        "Set selected animation hotkey",
        eFeatureType.Button,
        "Add the entered hotkey to the selected animation",
        function()
            local index = state.results:GetListIndex() + 1
            local selected = state.matches[index]
            if not selected or not selected.hash then
                safe_notify("Animation Search", "Select a matching animation first")
                return
            end

            local key_code = meow_search_key_code(state.hotkey_input:GetStringValue())
            if not key_code then
                safe_notify("Animation Search", "That hotkey is not valid")
                return
            end

            local target = FeatureMgr.GetFeature(selected.hash)
            if target and target.AddHotKey then
                target:AddHotKey(key_code)
            elseif HotKeyMgr and HotKeyMgr.AddHotkey then
                HotKeyMgr.AddHotkey(selected.hash, key_code)
            else
                safe_notify("Animation Search", "Could not find the selected animation feature")
                return
            end
            meow_hotkey_hashes[selected.hash] = true
            meow_hotkey_names[selected.hash] = tostring(selected.name or selected.hash)
            meow_save_hotkeys()
            safe_notify("Animation Search", "Hotkey added to " .. tostring(selected.name))
        end,
        true
    )

    state.hotkey_clear = FeatureMgr.AddFeature(
        state.hotkey_clear_hash,
        "Clear selected animation hotkeys",
        eFeatureType.Button,
        "Remove all hotkeys from the selected animation",
        function()
            local index = state.results:GetListIndex() + 1
            local selected = state.matches[index]
            if not selected or not selected.hash then
                safe_notify("Animation Search", "Select a matching animation first")
                return
            end

            local target = FeatureMgr.GetFeature(selected.hash)
            if target and target.ClearHotkeys then
                target:ClearHotkeys()
            elseif HotKeyMgr and HotKeyMgr.GetHotKeys and HotKeyMgr.RemoveHotkey then
                for _, key_code in ipairs(HotKeyMgr.GetHotKeys(selected.hash) or {}) do
                    HotKeyMgr.RemoveHotkey(selected.hash, key_code)
                end
            end
            meow_save_hotkeys()
            safe_notify("Animation Search", "Hotkeys cleared from " .. tostring(selected.name))
        end,
        true
    )

    for _, feature in ipairs({
        state.input, state.results, state.search, state.play, state.clear,
        state.hotkey_input, state.hotkey_add, state.hotkey_clear
    }) do
        if feature.SetSaveable then feature:SetSaveable(false) end
        if feature.SetSearchable then feature:SetSearchable(false) end
    end

    tab:AddFeature(state.input_hash)
    tab:AddFeature(state.list_hash)
    tab:AddFeature(state.search_hash)
    tab:AddFeature(state.play_hash)
    tab:AddFeature(state.clear_hash)
    tab:AddFeature(state.hotkey_input_hash)
    tab:AddFeature(state.hotkey_add_hash)
    tab:AddFeature(state.hotkey_clear_hash)
end

function meow_render_category_search(main_name, tab_name)
    local state = meow_category_search_render[tostring(main_name) .. "|" .. tostring(tab_name)]
    if not state or not ClickGUI or not ClickGUI.RenderFeature then return end

    local opened = true
    if ClickGUI.BeginCustomChildWindow then
        opened = ClickGUI.BeginCustomChildWindow("Animation Search")
    end
    if opened then
        ClickGUI.RenderFeature(state.input_hash)
        ClickGUI.RenderFeature(state.list_hash)
        ClickGUI.RenderFeature(state.search_hash)
        ClickGUI.RenderFeature(state.play_hash)
        ClickGUI.RenderFeature(state.clear_hash)
        ClickGUI.RenderFeature(state.hotkey_input_hash)
        ClickGUI.RenderFeature(state.hotkey_add_hash)
        ClickGUI.RenderFeature(state.hotkey_clear_hash)
    end
    if ClickGUI.EndCustomChildWindow then ClickGUI.EndCustomChildWindow() end
end

function cx_toast(title, message)
    if GUI and GUI.AddToast then
        GUI.AddToast(tostring(title or "MeowEmotes"), tostring(message or ""), 3500, eToastPos and eToastPos.TOP_RIGHT or 0)
    elseif g_gui and g_gui.add_toast then
        g_gui.add_toast(tostring(title or "MeowEmotes"), tostring(message or ""))
    else
        cx_log((title or "MeowEmotes") .. ": " .. tostring(message or ""))
    end
end

function cx_hash(value)
    if type(value) == "number" then return value end
    local hasher = rawget(_G, "joaat")
    if type(hasher) == "function" and hasher ~= cx_hash then return hasher(value) end
    if Utils and Utils.Joaat then return Utils.Joaat(value) end
    if MISC and MISC.GET_HASH_KEY then return MISC.GET_HASH_KEY(value) end
    return value
end

function meow_safe_remove_feature(hash)
    if FeatureMgr and FeatureMgr.RemoveFeature then
        FeatureMgr.RemoveFeature(hash)
    end
end

function meow_safe_add_feature(hash, name, feature_type, desc, callback, native_thread_execution, force_queue)
    if not (FeatureMgr and FeatureMgr.AddFeature) then return nil end
    return FeatureMgr.AddFeature(
        hash,
        tostring(name or "Feature"),
        feature_type,
        tostring(desc or ""),
        callback,
        native_thread_execution ~= false,
        force_queue == true
    )
end

function meow_safe_tab_add_feature(tab, hash)
    if tab and tab.AddFeature and hash then
        tab:AddFeature(hash)
    end
end

function meow_safe_get_sub_tab(tab, name)
    if tab and tab.GetSubTab then return tab:GetSubTab(name) end
    return nil
end

function meow_safe_add_sub_tab(tab, name, desc)
    if tab and tab.AddSubTab then return tab:AddSubTab(name, desc or name) end
    return nil
end

function meow_safe_render_feature(hash)
    if ClickGUI and ClickGUI.RenderFeature and hash then
        ClickGUI.RenderFeature(hash)
    end
end

joaat = joaat or cx_hash
ShouldUnload = ShouldUnload or function() return false end
unpack_args = table.unpack or unpack

function cx_player_ped()
    if PLAYER and PLAYER.PLAYER_PED_ID then return PLAYER.PLAYER_PED_ID() end
    if GTA and GTA.GetLocalPed and GTA.PointerToHandle then
        local ped_ptr = GTA.GetLocalPed()
        if ped_ptr ~= nil then return GTA.PointerToHandle(ped_ptr) end
    end
    if GTA and GTA.GetLocalPlayerId and PLAYER and PLAYER.GET_PLAYER_PED_SCRIPT_INDEX then
        return PLAYER.GET_PLAYER_PED_SCRIPT_INDEX(GTA.GetLocalPlayerId())
    end
    return 0
end

function cx_pad_pressed(group, control)
    if PAD and PAD.IS_CONTROL_PRESSED then
        return PAD.IS_CONTROL_PRESSED(group or 0, control or 0)
    end
    return false
end

function cx_pad_just_pressed(group, control)
    if PAD and PAD.IS_DISABLED_CONTROL_JUST_PRESSED then
        return PAD.IS_DISABLED_CONTROL_JUST_PRESSED(group or 0, control or 0)
    end
    if invoker and invoker.call then
        return invoker.call(0x580417101DDB492F, group or 0, control or 0).bool
    end
    return false
end

function cx_disable_control(group, control, toggle)
    if PAD and PAD.DISABLE_CONTROL_ACTION then
        PAD.DISABLE_CONTROL_ACTION(group or 0, control or 0, toggle ~= false)
    end
end

