function require(name)
    if name == "natives" then return native end
    return nil
end

util = util or {}
util.yield = util.yield or function(ms) Script.Yield(ms or 0) end
util.get_tick_count = util.get_tick_count or function() return Time and Time.GetEpocheMs and Time.GetEpocheMs() or MISC.GET_GAME_TIMER() end
util.current_time_millis = util.current_time_millis or util.get_tick_count
util.create_job = util.create_job or function(fn, ...) Script.QueueJob(fn, ...) end
util.create_thread = util.create_thread or function(fn)
    Script.QueueJob(function()
        while not ShouldUnload() do
            fn()
            Script.Yield(0)
        end
    end)
end

players = players or {}
players.me = players.me or function()
    local ped = cx_player_ped()
    local coords = invoke(0x3FEF770D40960D5A, ped, false).scr_vec3
    return {
        ped = ped,
        coords = coords,
        alive = not invoke(0x5F9532F3B5CC2551, ped, false).bool,
        heading = Natives.InvokeFloat(0xE83D4F9BA2A38914, ped),
    }
end

game = game or {}
game.in_game = game.in_game or function() return true end
game.state = game.state or function() return 0 end

input = input or {}
input.key = input.key or function()
    return { pressed = cx_pad_pressed(0, 73) }
end

invoker = invoker or {}
invoker.call = invoker.call or function(hash, ...)
    if not hash or hash == 0 then
        return { int = 0, bool = false, scr_vec3 = { x = 0, y = 0, z = 0 } }
    end

    local args = { ... }
    if hash == 0xD80958FC74E988A6 or hash == 0x43A66C31C68491C0 then
        return { int = cx_player_ped() }
    elseif hash == 0x3FEF770D40960D5A then
        return invoke(hash, unpack_args(args))
    elseif hash == 0x9CD27B0045628463 then
        return invoke(hash)
    elseif hash == 0x91AEF906BCA88877 then
        return { bool = cx_pad_just_pressed(args[1] or 0, args[2] or 0) }
    elseif hash == 0xFE99B66D079CF6BC then
        cx_disable_control(args[1] or 0, args[2] or 0, args[3] ~= false)
        return {}
    elseif hash == 0x6EA47DAE7FAD0EED then
        return invoke(hash, unpack_args(args))
    elseif hash == 0xC4EA073D86FB29B0 then
        return invoke(hash, unpack_args(args))
    elseif hash == 0xAF8A94EDE7712BEF then
        return invoke(hash, unpack_args(args))
    elseif hash == 0xAA74EC0CB0AAEA2C then
        return invoke(hash, unpack_args(args))
    elseif hash == 0x29A28F3F8CF6D854 then
        return invoke(hash, unpack_args(args))
    elseif hash == 0x20510814175EA477 then
        return invoke(hash, unpack_args(args))
    elseif hash == 0x2622E35B77D3ACA2 then
        return invoke(hash, unpack_args(args))
    elseif hash == 0x97B0DB5B4AA74E77 then
        return invoke(hash, unpack_args(args))
    elseif hash == 0x997ABD671D25CA0B then
        return invoke(hash, unpack_args(args))
    elseif hash == 0x5F9532F3B5CC2551 then
        return invoke(hash, unpack_args(args))
    elseif hash == 0x47E4E977581C5B55 or hash == 0xFB92A102F1C4DFA3 or hash == 0xCEDABC5900A0BF97 or hash == 0x9DE327631295B4C2 or hash == 0x53E8CB4F48BFE623 then
        return { bool = false }
    elseif hash == 0x44CB6447D2571AA0 then
        if PED.SET_PED_WETNESS_HEIGHT then PED.SET_PED_WETNESS_HEIGHT(args[1], args[2]) end; return {}
    elseif hash == 0x48C2BED9180FE123 then
        return { int = Natives.InvokeInt(hash, unpack_args(args)) }
    elseif Natives and Natives.InvokeInt then
        return { int = Natives.InvokeInt(hash, unpack_args(args)) }
    end
    return { int = 0, bool = false, scr_vec3 = { x = 0, y = 0, z = 0 } }
end

menu = menu or {}
menu.event = menu.event or { click = 1 }
menu.flags = menu.flags or { hotkey = 1, disabled = 2 }
menu.slider = menu.slider or { press = 1, scroll = 2 }
menu.notify = menu.notify or function(message) cx_toast("MeowEmotes", message) end

function feature_hash(path, label)
    return cx_hash("meow_" .. tostring(path or "root") .. "_" .. tostring(label or "feature"))
end

function meow_script_directory()
    local source = debug and debug.getinfo and debug.getinfo(1, "S").source
    if source and source:sub(1, 1) == "@" then
        local folder = source:sub(2):match("^(.*[\\/])")
        if folder and folder ~= "" then return folder end
    end

    if FileMgr and FileMgr.GetMenuRootPath then
        local root = FileMgr.GetMenuRootPath()
        if root and root ~= "" then
            if root:sub(-1) ~= "\\" and root:sub(-1) ~= "/" then root = root .. "\\" end
            return root .. "Lua\\"
        end
    end

    return ""
end

function meow_data_directory()
    local folder = meow_script_directory() .. "MeowPartyEmotes\\"
    if FileMgr and FileMgr.CreateDir then FileMgr.CreateDir(folder) end
    return folder
end

_G.MeowPartyScriptDir = meow_script_directory()
_G.MeowPartyDataDir = meow_data_directory()

function meow_default_hotkey_file()
    return (_G.MeowPartyDataDir or "") .. "MeowPartyEmotesHotkeys.json"
end

meow_hotkey_file = meow_default_hotkey_file()
meow_saved_hotkeys = {}
meow_hotkey_hashes = {}
meow_hotkey_names = {}
meow_hotkeys_loaded = false

function meow_read_file(path)
    if not io or not io.open then return nil end

    local f = io.open(path, "r")
    if not f then return nil end

    local text = f:read("*a")
    f:close()
    return text
end

function meow_write_file(path, text)
    if not io or not io.open then return false end

    local f = io.open(path, "w")
    if not f then return false end

    f:write(text or "")
    f:close()
    return true
end

meow_old_hotkey_file = (_G.MeowPartyScriptDir or "") .. "MeowPartyEmotesHotkeys.json"
if not meow_read_file(meow_hotkey_file) then
    meow_old_hotkey_text = meow_read_file(meow_old_hotkey_file)
    if meow_old_hotkey_text then meow_write_file(meow_hotkey_file, meow_old_hotkey_text) end
end

function meow_json_escape(value)
    value = tostring(value or "")
    value = value:gsub("\\", "\\\\")
    value = value:gsub("\"", "\\\"")
    value = value:gsub("\r", "\\r")
    value = value:gsub("\n", "\\n")
    return value
end

function meow_hotkey_block(text, hash)
    local key = "\"" .. tostring(hash) .. "\"%s*:%s*{"
    local start_pos = text:find(key)
    if not start_pos then return nil end

    local next_pos = text:find("\n%s*\"%d+\"%s*:%s*{", start_pos + 1)
    if next_pos then
        return text:sub(start_pos, next_pos - 1), start_pos, next_pos - 1
    end

    local close_pos = text:find("\n}", start_pos + 1)
    if close_pos then
        return text:sub(start_pos, close_pos - 1), start_pos, close_pos - 1
    end

    return text:sub(start_pos), start_pos, #text
end

function meow_parse_hotkeys(block)
    local keys = {}
    local raw = block and block:match("\"Hotkeys\"%s*:%s*%[(.-)%]")
    if not raw then return keys end

    for key in raw:gmatch("[^,%s]+") do
        local value = tonumber(key)
        if value then
            keys[#keys + 1] = value
        end
    end

    return keys
end

function meow_format_hotkeys(keys)
    local parts = {}

    for _, key in ipairs(keys or {}) do
        local value = tonumber(key)
        if value then
            parts[#parts + 1] = tostring(value)
        end
    end

    return table.concat(parts, ", ")
end

function meow_format_settings_entry(hash, name, keys)
    return string.format(
        "    \"%s\": {\n        \"Name\": \"%s\",\n        \"Hotkeys\": [%s]\n    }",
        tostring(hash),
        meow_json_escape(name),
        meow_format_hotkeys(keys)
    )
end

function meow_load_hotkeys()
    if meow_hotkeys_loaded then return end
    meow_hotkeys_loaded = true

    local text = meow_read_file(meow_hotkey_file)
    if not text then return end

    for hash, block in text:gmatch("\"(%d+)\"%s*:%s*{(.-)%f[\n]%s*}%s*,?") do
        local saved_hash = tonumber(hash)
        if saved_hash then
            meow_saved_hotkeys[saved_hash] = meow_parse_hotkeys(block)
        end
    end
end

function meow_apply_hotkeys(hash, feature, name)
    meow_load_hotkeys()
    meow_hotkey_hashes[hash] = true
    meow_hotkey_names[hash] = tostring(name or hash)

    local keys = meow_saved_hotkeys[hash]
    if not keys then return end

    for _, key in ipairs(keys) do
        local value = tonumber(key)
        if value then
            if HotKeyMgr and HotKeyMgr.AddHotkey then
                HotKeyMgr.AddHotkey(hash, value)
            end
            if feature and feature.AddHotKey then
                feature:AddHotKey(value)
            end
        end
    end
end

function meow_save_hotkeys()
    if not HotKeyMgr and not FeatureMgr then return end

    local entries = {}

    for hash in pairs(meow_hotkey_hashes) do
        local keys = nil
        if HotKeyMgr and HotKeyMgr.GetHotKeys then
            keys = HotKeyMgr.GetHotKeys(hash)
        elseif FeatureMgr and FeatureMgr.GetFeature then
            local feature = FeatureMgr.GetFeature(hash)
            if feature and feature.GetHotkeys then keys = feature:GetHotkeys() end
        end

        if keys then
            local clean_keys = {}
            for _, key in ipairs(keys) do
                local value = tonumber(key)
                if value then
                    clean_keys[#clean_keys + 1] = value
                end
            end

            if #clean_keys > 0 then
                entries[#entries + 1] = {
                    hash = hash,
                    name = meow_hotkey_names[hash] or hash,
                    keys = clean_keys
                }
            end
        end
    end

    table.sort(entries, function(a, b)
        return tostring(a.name) < tostring(b.name)
    end)

    local parts = {}
    for _, entry in ipairs(entries) do
        parts[#parts + 1] = meow_format_settings_entry(entry.hash, entry.name, entry.keys)
    end

    local text = "{\n" .. table.concat(parts, ",\n") .. "\n}"
    if meow_read_file(meow_hotkey_file) == text then return end

    meow_write_file(meow_hotkey_file, text)
end

function meow_start_hotkey_saver()
    if meow_hotkey_saver_started then return end
    if not ((util and util.create_thread) or (EventMgr and eLuaEvent and eLuaEvent.ON_UNLOAD)) then return end
    meow_hotkey_saver_started = true

    if EventMgr and eLuaEvent and eLuaEvent.ON_UNLOAD then
        EventMgr.RegisterHandler(eLuaEvent.ON_UNLOAD, function()
            meow_save_hotkeys()
        end)
    end

    if util and util.create_thread then
        util.create_thread(function()
            while true do
                meow_save_hotkeys()
                util.yield(10000)
            end
        end)
    end
end

MenuNode = {}
MenuNode.__index = MenuNode

function new_node(path)
    return setmetatable({ path = path or "Meow" }, MenuNode)
end

function decorate_option(option)
    function option:flags(...) return self end
    function option:tooltip(...) return self end
    function option:fmt(...) return self end
    return option
end

cherax_ui_entries = {}
cherax_ui_tab_added = false
cherax_list_tabs = {}
cherax_root_tab = nil
cherax_script_tab = nil

function cherax_clean_segment(text)
    text = tostring(text or "Root")
    text = text:gsub("^%s+", ""):gsub("%s+$", "")
    if text == "" then text = "Root" end
    return text
end

function cherax_pretty_segment(segment)
    local text = cherax_clean_segment(segment)
    local key = text:lower():gsub("^%s+", ""):gsub("%s+$", "")

    local names = {
        idle = "Idle",
        sit = "Sitting",
        romance = "Romance",
        dances = "Dances",
        props = "Props",
        actions = "Actions",
        misc = "Misc",
        crouch = "Crouch",
        extras = "Extras",
        sexcar = "Vehicle",
        mechanic = "Mechanic",
        medic = "Medic",
        favorites = "Favorites",
        partnered = "Partnered",
        freestyle = "Freestyle",
        casual = "Casual",
        disco = "Disco",
        guitars = "Guitars",
        guns = "Guns",
        melee = "Melee",
        plushies = "Plushies",
        snacks = "Snacks",
        scenarios = "Scenarios",
        chains = "Chains",
        utilsdelete = "UtilsDelete",
    }

    if names[key] then return names[key] end
    if key == "meowstuffs" then return "Accessories" end
    if key == "meowdances" then return "Meow Dances" end
    if key == " sexual(21+)" or key == "sexual(21+)" then return "Adult" end
    if key:find("walking styles", 1, true) then return "Walk Styles" end
    if key:find("world sit", 1, true) then return "World Sitting" end
    if key:find("meow xo", 1, true) then return "Cute" end
    if key:find("nightclub high", 1, true) then return "Nightclub High"
    elseif key:find("nightclub medium", 1, true) then return "Nightclub Medium"
    elseif key:find("nightclub low", 1, true) then return "Nightclub Low"
    elseif key:find("after party high", 1, true) then return "After Party High"
    elseif key:find("after party medium", 1, true) then return "After Party Medium"
    elseif key:find("after party low", 1, true) then return "After Party Low"
    elseif key:find("island party high", 1, true) then return "Island Party High"
    elseif key:find("island party medium", 1, true) then return "Island Party Medium"
    elseif key:find("island party low", 1, true) then return "Island Party Low"
    end

    return text:gsub("^%l", string.upper)
end

function cherax_menu_segments(path)
    local raw = tostring(path or "")
    local mapped = {}

    for segment in raw:gmatch("[^/]+") do
        local clean_segment = cherax_clean_segment(segment)
        if clean_segment ~= "" and clean_segment ~= "Root" and clean_segment ~= "MeowEyePartyEmotes" then
            mapped[#mapped + 1] = cherax_pretty_segment(clean_segment)
        end
    end

    return mapped
end

function cherax_top_category(path)
    local parts = cherax_menu_segments(path)
    return parts[1] or "Root"
end


function cherax_main_category(path)
    local raw = tostring(path or "")
    local first = nil
    for segment in raw:gmatch("[^/]+") do
        local clean_segment = cherax_clean_segment(segment)
        if clean_segment ~= "" and clean_segment ~= "Root" and clean_segment ~= "MeowEyePartyEmotes" then
            first = clean_segment
            break
        end
    end

    local key = tostring(first or "Self"):lower():gsub("^%s+", ""):gsub("%s+$", "")
    if key == "romance" then return "Romance" end
    if key == "idle" then return "Idle" end
    if key == "sit" or key == "sitting" then return "Sit" end
    if key == "dances" then return "Dances" end
    if key == "props" then return "Props" end
    if key == "favorites" then return "Favorites" end
    if key == "utilsdelete" then return "UtilsDelete" end
    if key:find("walking styles", 1, true) then return "Walk Styles" end
    if key:find("world sit", 1, true) then return "World" end
    return "Self"
end

function cherax_sub_tab(path)
    local parts = cherax_menu_segments(path)
    if #parts == 0 then return "General" end
    if #parts == 1 then return parts[1] end
    return parts[#parts]
end

function cherax_render_feature_entry(entry)
    if not entry then return end
    if ClickGUI and ClickGUI.RenderFeature and entry.hash then
        ClickGUI.RenderFeature(entry.hash)
        return
    end

    local label = tostring(entry.name or entry.label or "Action")
    local clicked = false
    if ImGui and ImGui.Button then
        clicked = ImGui.Button(label .. "##meow_custom_" .. tostring(entry.hash or label))
    elseif ImGui and ImGui.Selectable then
        clicked = ImGui.Selectable(label)
    end

    if clicked and entry.callback then
        Script.QueueJob(entry.callback)
    end
end

function cherax_render_feature_group(title, entries)
    if not entries or #entries == 0 then return end

    local opened = true
    if ClickGUI and ClickGUI.BeginCustomChildWindow then
        opened = ClickGUI.BeginCustomChildWindow(title)
    elseif ImGui and ImGui.SeparatorText then
        ImGui.SeparatorText(title)
    elseif ImGui and ImGui.Text then
        ImGui.Text(title)
    end

    if opened then
        for _, entry in ipairs(entries) do
            cherax_render_feature_entry(entry)
        end
    end

    if ClickGUI and ClickGUI.EndCustomChildWindow then
        ClickGUI.EndCustomChildWindow()
    end
end

function cherax_entries_for_category(category)
    local groups = {}
    local order = {}

    for _, entry in ipairs(cherax_ui_entries) do
        if entry.category == category then
            local group = entry.group or "General"
            if not groups[group] then
                groups[group] = {}
                order[#order + 1] = group
            end
            groups[group][#groups[group] + 1] = entry
        end
    end

    return groups, order
end

function cherax_render_group_columns(groups, order, column_id)
    if ImGui and ImGui.Columns then ImGui.Columns(2, column_id, false) end

    for index, group in ipairs(order) do
        cherax_render_feature_group(group, groups[group])
        if ImGui and ImGui.NextColumn and index % 2 == 1 then
            ImGui.NextColumn()
        end
    end

    if ImGui and ImGui.Columns then ImGui.Columns() end
end

function cherax_entries_for_tab(main_name, tab_name)
    local entries = {}
    for _, entry in ipairs(cherax_ui_entries) do
        if entry.main == main_name and entry.tab == tab_name then
            entries[#entries + 1] = entry
        end
    end
    return entries
end

function cherax_sub_tabs_for_main(main_name)
    local tabs = {}
    local seen = {}

    for _, entry in ipairs(cherax_ui_entries) do
        if entry.main == main_name then
            local tab = entry.tab or "General"
            if not seen[tab] then
                seen[tab] = true
                tabs[#tabs + 1] = tab
            end
        end
    end

    return tabs
end

function cherax_render_tab_content(main_name, tab_name)
    local entries = cherax_entries_for_tab(main_name, tab_name)
    meow_render_category_search(main_name, tab_name)
    if #entries == 0 then
        return
    end

    cherax_render_feature_group(tab_name, entries)
end

function cherax_render_main_category(main_name)
    local tabs = cherax_sub_tabs_for_main(main_name)
    if #tabs == 0 then
        return
    end

    if #tabs == 1 then
        cherax_render_tab_content(main_name, tabs[1])
        return
    end

    local flags = ImGuiTabBarFlags and ImGuiTabBarFlags.None or 0
    if #tabs > 8 then
        local per_page = math.ceil(#tabs / 3)
        if ImGui.BeginTabBar("MeowSubPages_" .. main_name, flags) then
            for page = 1, 3 do
                local first = ((page - 1) * per_page) + 1
                local last = math.min(page * per_page, #tabs)

                if first <= #tabs and ImGui.BeginTabItem(tostring(page)) then
                    if ImGui.BeginTabBar("MeowSubTabs_" .. main_name .. "_" .. tostring(page), flags) then
                        for index = first, last do
                            local tab = tabs[index]
                            if ImGui.BeginTabItem(tab) then
                                cherax_render_tab_content(main_name, tab)
                                ImGui.EndTabItem()
                            end
                        end

                        ImGui.EndTabBar()
                    end

                    ImGui.EndTabItem()
                end
            end

            ImGui.EndTabBar()
        end

        return
    end

    if ImGui.BeginTabBar("MeowSubTabs_" .. main_name, flags) then
        for _, tab in ipairs(tabs) do
            if ImGui.BeginTabItem(tab) then
                cherax_render_tab_content(main_name, tab)
                ImGui.EndTabItem()
            end
        end

        ImGui.EndTabBar()
    end
end

function cherax_render_tab()
    if not ImGui then return end

    local flags = ImGuiTabBarFlags and ImGuiTabBarFlags.None or 0
    if not ImGui.BeginTabBar("MeowMainTabs", flags) then
        return
    end

    local categories = { "Self", "Dances", "Romance", "Idle", "Sit", "Props", "Walk Styles", "World", "Favorites", "UtilsDelete", "HUD" }
    for _, category in ipairs(categories) do
        if ImGui.BeginTabItem(category) then
            cherax_render_main_category(category)
            ImGui.EndTabItem()
        end
    end

    ImGui.EndTabBar()
end

function cherax_ensure_tab()
    if cherax_ui_tab_added then return end
    if ClickGUI and ClickGUI.AddTab then
        ClickGUI.RemoveTab("MeowEmotes")
        ClickGUI.AddTab("MeowEmotes", cherax_render_tab)
        cherax_ui_tab_added = true
    end
end

function cherax_get_root_tab()
    if cherax_root_tab and cherax_script_tab then return cherax_root_tab end
    if not (ListGUI and ListGUI.GetRootTab) then return nil end

    cherax_root_tab = ListGUI.GetRootTab()
    if not cherax_root_tab then return nil end

    local stale = cherax_root_tab:GetSubTab("MeowEyePartyEmotes")
    if stale then
        cherax_root_tab:RemoveSubTab(stale)
    end

    cherax_script_tab = cherax_root_tab:GetSubTab("MeowEmotes")
    if not cherax_script_tab then
        cherax_script_tab = cherax_root_tab:AddSubTab("MeowEmotes", "Meow party emotes")
    end

    cherax_list_tabs["CheraxRoot"] = cherax_root_tab
    cherax_list_tabs["CheraxRoot/MeowEmotes"] = cherax_script_tab
    return cherax_root_tab
end

function meow_path_needs_animation_search(path)
    local normalized = tostring(path or ""):lower()

    if not normalized:find("meoweyepartyemotes", 1, true) then
        return false
    end

    local after_root = normalized:match("meoweyepartyemotes%s*/%s*(.+)")
    if not after_root or after_root == "" then
        return false
    end

    if normalized:find("utilsdelete", 1, true)
    or normalized:find("crouch", 1, true)
    or normalized:find("walking styles", 1, true)
    or normalized:find("favorites", 1, true)
    or normalized:find("glowsticks", 1, true)
    or normalized:find("search radius", 1, true)
    or normalized:find("world sitting", 1, true)
    or normalized:find("world sit", 1, true)
    or normalized:find("/ sit", 1, true)
    or normalized:find("/ sitting", 1, true) then
        return false
    end

    if normalized:find("/ props", 1, true)
    and not normalized:find("clan_xo", 1, true) then
        return false
    end

    return true
end

function cherax_tab_for_path(path)
    local root_tab = cherax_get_root_tab()
    if not root_tab then return nil end

    local parent = cherax_script_tab or root_tab:GetSubTab("MeowEmotes") or root_tab:AddSubTab("MeowEmotes", "Meow party emotes")
    cherax_script_tab = parent
    local key = "CheraxRoot/MeowEmotes"
    local parts = cherax_menu_segments(path)

    if #parts == 0 then
        parts = { "Self", "General" }
    end

    for _, segment in ipairs(parts) do
        local clean_segment = cherax_clean_segment(segment)
        key = key .. "/" .. clean_segment
        if not cherax_list_tabs[key] then
            local existing = parent:GetSubTab(clean_segment)
            if existing then
                cherax_list_tabs[key] = existing
            else
                cherax_list_tabs[key] = parent:AddSubTab(clean_segment, clean_segment)
            end
        end
        parent = cherax_list_tabs[key]
    end

    if meow_path_needs_animation_search(path) then
        meow_category_search(parent, key, path)
    end
    return parent
end

function MenuNode:submenu(label)
    return new_node((self.path ~= "" and (self.path .. " / ") or "") .. tostring(label))
end

function MenuNode:breaker(label)
    cx_log("[MeowEmotes] " .. self.path .. " / " .. tostring(label))
    return decorate_option({ value = 0 })
end

function MenuNode:button(label)
    local option = decorate_option({ value = false })
    function option:event(_, callback)
        local display = self.path .. " / " .. tostring(label)
        local hash = feature_hash(self.path, label)
        FeatureMgr.RemoveFeature(hash)
        local feature = FeatureMgr.AddFeature(hash, tostring(label), eFeatureType.Button, display, function()
            Script.QueueJob(function() callback(option) end)
        end, true)
        if feature and feature.SetSearchable then feature:SetSearchable(true) end
        if feature and feature.SetSaveable then feature:SetSaveable(false) end
        if feature and feature.RegisterCallbackTrigger and eCallbackTrigger and eCallbackTrigger.OnClick then feature:RegisterCallbackTrigger(eCallbackTrigger.OnClick) end
        meow_apply_hotkeys(hash, feature, display)
        meow_start_hotkey_saver()
        local tab = cherax_tab_for_path(self.path)
        if tab then
            tab:AddFeature(hash)
        end
        cherax_ui_entries[#cherax_ui_entries + 1] = {
            hash = hash,
            name = tostring(label),
            label = display,
            category = cherax_top_category(self.path),
            main = cherax_main_category(self.path),
            group = (cherax_menu_segments(self.path)[2] or "General"),
            tab = cherax_sub_tab(self.path),
            callback = function() callback(option) end,
        }
        cherax_ensure_tab()
        if g_gui and g_gui.add_button then
            g_gui.add_button("misc_lua", display, function()
                Script.QueueJob(function() callback(option) end)
            end)
        end
        return option
    end
    option.path = self.path
    return option
end

function MenuNode:toggle(label)
    local option = decorate_option({ value = false })
    function option:event(_, callback)
        local display = self.path .. " / " .. tostring(label)
        local hash = feature_hash(self.path, label)
        FeatureMgr.RemoveFeature(hash)
        local feature_obj = FeatureMgr.AddFeature(hash, tostring(label), eFeatureType.Toggle, display, function(feature)
            option.value = feature and feature.IsToggled and feature:IsToggled() or not option.value
            Script.QueueJob(function() callback(option) end)
        end, true)
        if feature_obj and feature_obj.SetSearchable then feature_obj:SetSearchable(true) end
        if feature_obj and feature_obj.SetSaveable then feature_obj:SetSaveable(false) end
        if feature_obj and feature_obj.RegisterCallbackTrigger and eCallbackTrigger and eCallbackTrigger.OnClick then feature_obj:RegisterCallbackTrigger(eCallbackTrigger.OnClick) end
        meow_apply_hotkeys(hash, feature_obj, display)
        meow_start_hotkey_saver()
        local tab = cherax_tab_for_path(self.path)
        if tab then
            tab:AddFeature(hash)
        end
        cherax_ui_entries[#cherax_ui_entries + 1] = {
            hash = hash,
            name = tostring(label),
            label = display .. " [toggle]",
            category = cherax_top_category(self.path),
            main = cherax_main_category(self.path),
            group = (cherax_menu_segments(self.path)[2] or "General"),
            tab = cherax_sub_tab(self.path),
            callback = function()
                option.value = not option.value
                callback(option)
            end,
        }
        cherax_ensure_tab()
        if g_gui and g_gui.add_toggle then
            g_gui.add_toggle("misc_lua", display, function(on)
                option.value = on
                callback(option)
            end)
        end
        return option
    end
    option.path = self.path
    return option
end

function MenuNode:number_int(label)
    local option = decorate_option({ value = 0 })
    function option:event(_, callback) return option end
    return option
end

function MenuNode:number_float(label)
    local option = decorate_option({ value = 0.0 })
    function option:event(_, callback) return option end
    return option
end

function MenuNode:combo_int(label)
    local option = decorate_option({ value = 1, list = { at = function(_, index) return { value = index } end } })
    function option:event(_, callback) return option end
    return option
end

