function invoke(hash, ...)
    if not hash or hash == 0 then
        return { int = 0, bool = false, scr_vec3 = { x = 0, y = 0, z = 0 } }
    end

    local args = { ... }

    if hash == 0x3FEF770D40960D5A then
        local x, y, z = Natives.InvokeV3(hash, unpack_args(args))
        return { scr_vec3 = { x = x, y = y, z = z }, x = x, y = y, z = z }
    end

    if hash == 0x509D5878EB39E842 or hash == 0x9A294B2138ABB884 then
        local obj = GTA.CreateObject(args[1], args[2], args[3], args[4], true, true)
        return { int = obj or 0, bool = obj ~= nil and obj ~= 0 }
    end

    if hash == 0xAE3CBE5BF394C9C9 then
        local entity = args[1]
        if entity and entity ~= 0 then
            local ptr = Memory.AllocInt()
            Memory.WriteInt(ptr, entity)
            Natives.InvokeVoid(hash, ptr)
            Memory.Free(ptr)
        end
        return {}
    end

    local bool_hashes = {
        [0x7239B21A38F536BA] = true,
        [0x524AC5ECEA15343E] = true,
        [0x01BF60A500E28887] = true,
        [0x98A4EB5D89A0C952] = true,
        [0xD031A9162D01088C] = true,
        [0xC4EA073D86FB29B0] = true,
        [0x997ABD671D25CA0B] = true,
        [0x5F9532F3B5CC2551] = true,
    }

    local int_hashes = {
        [0x3F428D08BE5AAE31] = true,
        [0xD80958FC74E988A6] = true,
        [0x9CD27B0045628463] = true,
        [0x2C83A9DA6BFFC4F9] = true,
    }

    local float_hashes = {
        [0xFEDDF04D62B8D790] = true,
    }

    if bool_hashes[hash] then
        local ok = Natives.InvokeBool(hash, unpack_args(args))
        return { bool = ok, int = ok and 1 or 0 }
    end

    if int_hashes[hash] then
        local value = Natives.InvokeInt(hash, unpack_args(args))
        return { int = value, bool = value ~= 0 }
    end

    if float_hashes[hash] then
        local value = Natives.InvokeFloat(hash, unpack_args(args))
        return { float = value, int = math.floor(value), bool = value ~= 0.0 }
    end

    Natives.InvokeVoid(hash, unpack_args(args))
    return { int = 0, bool = false }
end

