native.set_mobile_phone_position = function(x, y, z)
    if invoker and invoker.call and scr_vec3 then
        local pos = scr_vec3()
        pos.x = x or -10000.0
        pos.y = y or 0.0
        pos.z = z or 0.0
        invoker.call(0x693A5C6D6734085B, pos)
        return
    end
    if invoker and invoker.call then
        invoker.call(0x693A5C6D6734085B, x or -10000.0, y or 0.0, z or 0.0)
        return
    end
    if MOBILE and MOBILE.SET_MOBILE_PHONE_POSITION then return MOBILE.SET_MOBILE_PHONE_POSITION(x or -10000.0, y or 0.0, z or 0.0) end
    invoke(0x693A5C6D6734085B, x or -10000.0, y or 0.0, z or 0.0)
end
native.get_mobile_phone_position = function()
    if invoker and invoker.call and scr_vec3 then
        local pos = scr_vec3()
        invoker.call(0x584FDFDA48805B86, pos)
        return pos
    end
    if MOBILE and MOBILE.GET_MOBILE_PHONE_POSITION and scr_vec3 then
        local pos = scr_vec3()
        MOBILE.GET_MOBILE_PHONE_POSITION(pos)
        return pos
    end
    return { x = 0.0, y = 0.0, z = 0.0 }
end
