function get_ped_bone_index(ped, boneId)
    if boneId and boneId >= 0 and boneId < 200 then
        return boneId
    end

    return invoke(GET_PED_BONE_INDEX, ped, boneId).int
end

DOES_ENTITY_EXIST             = 0x7239B21A38F536BA
NETWORK_HAS_CONTROL_OF_ENTITY = 0x01BF60A500E28887
NETWORK_REQUEST_CONTROL       = 0xB69317BF5E782347
SET_ENTITY_AS_MISSION_ENTITY  = 0xAD738C3085FE7E11
DELETE_ENTITY                 = 0xAE3CBE5BF394C9C9

function sink_entity(entity)
    if entity and entity ~= 0 and invoke(DOES_ENTITY_EXIST, entity) then

        if not invoke(NETWORK_HAS_CONTROL_OF_ENTITY, entity) then
            invoke(NETWORK_REQUEST_CONTROL, entity)
        end

        invoke(SET_ENTITY_AS_MISSION_ENTITY, entity, true, true)
        invoke(DELETE_ENTITY, entity)
    end
end

