function trim(s)
    if type(s) ~= "string" then
        return s
    end

    return (s:gsub("^%s+", ""):gsub("%s+$", ""))
end

function yield_ms(ms)
    Script.Yield(ms or 0)
end

function safe_notify(title, msg)
    cx_toast(title, msg)
    print("[" .. title .. "] " .. msg)
end

function notify_attach(msg)
    safe_notify("Emotes", "Attach: " .. msg)
end

function native_call(fn, ...)
    if type(fn) ~= "function" then
        return false
    end

    return true, fn(...)
end

function invoker_call(hash, ...)
    if not invoker or not invoker.call then
        return false
    end

    return true, invoker.call(hash, ...)
end

function invoker_int(hash, ...)
    local ok, result = invoker_call(hash, ...)
    if ok and result then
        return result.int
    end
end

function set_cat_pickup_state(cat, enabled)
    native_call(native.set_entity_collision, cat, not enabled, not enabled)
    native_call(native.set_blocking_of_non_temporary_events, cat, enabled)
    native_call(native.set_ped_can_ragdoll, cat, not enabled)
end

GET_ENTITY_COORDS                = 0x3FEF770D40960D5A
REQUEST_MODEL                    = 0x963D27A58DF860AC
HAS_MODEL_LOADED                 = 0x98A4EB5D89A0C952
CREATE_OBJECT                    = 0x509D5878EB39E842
ATTACH_ENTITY_TO_ENTITY          = 0x6B9BBD38AB0796DF
SET_ENTITY_COMPLETELY_DISABLE_COLLISION = 0x9EBC85ED0FFFE51C
SET_MODEL_AS_NO_LONGER_NEEDED    = 0xE532F5D78798DAAB

function attach(model, bone, offx, offy, offz, rotx, roty, rotz, tableProp)
    local prop = attach_prop(model, bone, offx, offy, offz, rotx, roty, rotz, false)
    if prop and tableProp then
        table.insert(tableProp, prop)
    end
    return prop or 0
end
function addProps(t)

    if not t then
        return
    end

    for _, p in ipairs(t) do

        if type(p) == "table" then

            local m = p.hash or p.prop
            local b = p.bone

            local x, y, z
            local rx, ry, rz

            if p.pos and type(p.pos) == "table" then

                x  = p.pos[1]
                y  = p.pos[2]
                z  = p.pos[3]

                rx = p.pos[4]
                ry = p.pos[5]
                rz = p.pos[6]

            elseif p.offx ~= nil then

                x  = p.offx
                y  = p.offy
                z  = p.offz

                rx = p.rotx
                ry = p.roty
                rz = p.rotz
            end

            if m and b and x then
                attach(
                    m,
                    b,
                    x or 0.0,
                    y or 0.0,
                    z or 0.0,
                    rx or 0.0,
                    ry or 0.0,
                    rz or 0.0,
                    t.props
                )
            end
        end
    end
end

function ensure_anim_dict(dict)

    if not dict then
        return false
    end

    if anim_dict_cache[dict] then
        return true
    end

    cx_native.request_anim_dict(dict)

    local deadline =
        native.get_game_timer() + TIMEOUT_ANIM_MS

    while not cx_native.has_anim_dict_loaded(dict) do

        if native.get_game_timer() > deadline then

            log_warn(
                string.format(
                    "Anim dict load timed out: %s",
                    tostring(dict)
                )
            )

            return false
        end

        util.yield(0)
    end

    anim_dict_cache[dict] = true

    return true
end

REQUEST_MODEL          = 0x963D27A58DF860AC
HAS_MODEL_LOADED       = 0x98A4EB5D89A0C952

function request_model(hash)
    hash = type(hash) == "number" and hash or cx_hash(hash)
    if not hash or hash == 0 then
        return false
    end

    if model_cache[hash] then
        return true
    end

    Natives.InvokeVoid(REQUEST_MODEL, hash)

    local deadline = native.get_game_timer() + TIMEOUT_MODEL_MS
    while not Natives.InvokeBool(HAS_MODEL_LOADED, hash) do
        if native.get_game_timer() > deadline then
            log_warn(string.format("Model load timed out: %s", tostring(hash)))
            return false
        end

        Script.Yield(0)
    end

    model_cache[hash] = true
    return true
end

last_action = nil

function run_handler(label, handler, remember_last)

    if remember_last == nil then
        remember_last = true
    end

    if remember_last and handler then
        last_action = handler
    end

    handler()
end

function validate_item_fields(label, dict, anim, mode, scenario)

    if not label or label == "" then
        return false
    end

    if mode and mode ~= "" and not MODE_FLAGS[mode] then
        return false
    end

    if scenario and scenario ~= "" then
        return true
    end

    if dict and dict ~= "" and anim and anim ~= "" then
        return true
    end

    if (not dict or dict == "")
    and (not anim or anim == "") then
        return true
    end

    return false
end

