function ensure_ped()

    local ped = get_ped()

    if ped == 0 then

        safe_notify(
            "Emotes",
            "Player not found"
        )

        return nil
    end

    return ped
end

GET_ENTITY_COORDS                         = 0x3FEF770D40960D5A
CREATE_OBJECT_NO_OFFSET                  = 0x9A294B2138ABB884
SET_ENTITY_INVINCIBLE                    = 0x3882114BDE571AD4
SET_ENTITY_COLLISION                     = 0x1A9205C1B9EE827F
SET_ENTITY_COMPLETELY_DISABLE_COLLISION  = 0x9EBC85ED0FFFE51C
DOES_ENTITY_EXIST                        = 0x7239B21A38F536BA
DELETE_ENTITY                            = 0xAE3CBE5BF394C9C9
ATTACH_ENTITY_TO_ENTITY                  = 0x6B9BBD38AB0796DF
TASK_PLAY_ANIM                           = 0xEA47FE3719165B94
GET_ANIM_DURATION                        = 0xFEDDF04D62B8D790
GET_PED_BONE_INDEX                       = 0x3F428D08BE5AAE31

function attach_prop(
    hash,
    bone,
    offx,
    offy,
    offz,
    rotx,
    roty,
    rotz,
    skip_request
)
    local ped = ensure_ped()
    if not ped then return nil end

    hash = type(hash) == "number" and hash or cx_hash(hash)
    if not hash or hash == 0 then
        notify_attach("Missing hash for prop")
        return nil
    end

    if not skip_request and not request_model(hash) then
        log_warn(string.format("Model load timed out: %s", tostring(hash)))
        return nil
    end

    local x, y, z = Natives.InvokeV3(GET_ENTITY_COORDS, ped, true)
    local obj, created_hash = create_attachment_object(hash, x, y, z)

    if not obj or obj == 0 then
        log_warn(string.format("Create object failed for %s", tostring(hash)))
        return nil
    end

    Natives.InvokeVoid(SET_ENTITY_INVINCIBLE, obj, true)
    Natives.InvokeVoid(SET_ENTITY_COLLISION, obj, false, true)
    Natives.InvokeVoid(SET_ENTITY_COMPLETELY_DISABLE_COLLISION, obj, true, true)

    bone = tonumber(bone) or BONE.RIGHT_HAND
    local bone_idx = bone
    if bone >= 200 then
        bone_idx = Natives.InvokeInt(GET_PED_BONE_INDEX, ped, bone)
    end

    if not bone_idx or bone_idx == -1 then
        log_warn(string.format("Bone index not found for %s", tostring(bone)))
        sink_entity(obj)
        return nil
    end

    Natives.InvokeVoid(
        ATTACH_ENTITY_TO_ENTITY,
        obj,
        ped,
        bone_idx,
        offx or 0.0,
        offy or 0.0,
        offz or 0.0,
        rotx or 0.0,
        roty or 0.0,
        rotz or 0.0,
        false,
        false,
        false,
        false,
        2,
        true,
        false
    )

    Natives.InvokeVoid(SET_MODEL_AS_NO_LONGER_NEEDED, created_hash or hash)
    attached_objects[obj] = true

    return obj
end
function validate_attachment(a)

    if type(a) ~= "table" then
        return nil
    end

    local h = tonumber(a.hash)
    if not h and type(a.hash) == "string" then
        h = cx_hash(a.hash)
    end

    if not h then
        return nil
    end

    local b = tonumber(a.bone) or BONE.RIGHT_HAND

    return {
        hash = h,
        bone = b,

        offx = tonumber(a.offx) or 0.0,
        offy = tonumber(a.offy) or 0.0,
        offz = tonumber(a.offz) or 0.0,

        rotx = tonumber(a.rotx) or 0.0,
        roty = tonumber(a.roty) or 0.0,
        rotz = tonumber(a.rotz) or 0.0,
    }
end

function unsigned_hash(hash)
    if type(hash) == "number" and hash < 0 then
        return hash + 4294967296
    end

    return hash
end

function signed_hash(hash)
    if type(hash) == "number" and hash > 2147483647 then
        return hash - 4294967296
    end

    return hash
end

function attachment_hash_variants(hash)
    local variants = {}
    local seen = {}

    local function add(value)
        if type(value) == "number" and value ~= 0 and not seen[value] then
            variants[#variants + 1] = value
            seen[value] = true
        end
    end

    add(hash)
    add(unsigned_hash(hash))
    add(signed_hash(hash))

    return variants
end

function create_attachment_object(hash, x, y, z)
    for _, candidate in ipairs(attachment_hash_variants(hash)) do
        local obj = Natives.InvokeInt(CREATE_OBJECT_NO_OFFSET, candidate, x, y, z, true, true, false)
        if obj and obj ~= 0 then
            return obj, candidate
        end

        obj = GTA.CreateObject(candidate, x, y, z, true, true)
        if obj and obj ~= 0 then
            return obj, candidate
        end
    end

    return 0, hash
end

function request_attachment_model(hash)
    local primary = unsigned_hash(hash)
    if request_model(primary) then
        return primary
    end

    if primary ~= hash and request_model(hash) then
        return hash
    end

    return nil
end

function play_anim(dict, name, flags)

    if not ensure_anim_dict(dict) then
        return
    end

    local ped = ensure_ped()

    if not ped then
        return
    end

    native.task_play_anim(
        ped,
        dict,
        name,
        3.0,
        2.0,
        -1,
        flags or ANIM_FLAG.DEFAULT,
        0.0,
        false,
        false,
        false
    )
end

function play_emote(dict, name, mode)

    if not dict or not name then

        log_warn("play_emote: missing dict or anim")

        return
    end

    local flags =
        MODE_FLAGS[mode] or ANIM_FLAG.DEFAULT

    play_anim(dict, name, flags)
end
function play_emote_first_existing(
    dict,
    names,
    mode
)

    if not dict or not names then
        return false
    end

    local ped = ensure_ped()

    if not ped then
        return false
    end

    local list =
        type(names) == "table"
        and names
        or { names }

    local key =
        dict .. "|" .. table.concat(list, ";")

    if not ensure_anim_dict(dict) then
        return false
    end

    local flags =
        MODE_FLAGS[mode] or ANIM_FLAG.DEFAULT

    local function try_play(anim)

        if not anim then
            return false
        end

        native.task_play_anim(
            ped,
            dict,
            anim,
            3.0,
            2.0,
            -1,
            flags,
            0.0,
            false,
            false,
            false
        )

        return true
    end


    if resolved_anim_cache[key]
    and try_play(resolved_anim_cache[key]) then
        return true
    end


    for _, anim in ipairs(list) do

        if try_play(anim) then


            if resolved_anim_cache[key] == nil
            and (resolved_anim_cache.__size or 0)
                >= RESOLVED_CACHE_MAX then

                resolved_anim_cache = {}
                resolved_anim_cache.__size = 0
            end

            resolved_anim_cache[key] = anim

            resolved_anim_cache.__size =
                (resolved_anim_cache.__size or 0) + 1

            return true
        end
    end

    return false
end
