local phone_anim = {
    enabled = false,
    running = false,
    last_restart = 0,
    cooldown = 5000,
    flags = { 242, 243, 244 },
    script_hash = nil
}

local function phone_anim_hash()
    if not phone_anim.script_hash then
        phone_anim.script_hash = joaat("cellphone_flashhand")
    end
    return phone_anim.script_hash
end

local function phone_anim_set_flags(ped, value)
    if not ped or ped == 0 then return end
    for _, flag in ipairs(phone_anim.flags) do
        native_call(native.set_ped_config_flag, ped, flag, value)
    end
end

local function phone_anim_cleanup()
    local ped = ensure_ped()
    if ped and ped ~= 0 then
        if PED and PED.IS_PED_RUNNING_MOBILE_PHONE_TASK then
            local running = PED.IS_PED_RUNNING_MOBILE_PHONE_TASK(ped)
            if running then native_call(native.task_use_mobile_phone, ped, false, 0) end
        else
            native_call(native.task_use_mobile_phone, ped, false, 0)
        end
        phone_anim_set_flags(ped, false)
    end
    native_call(native.destroy_mobile_phone)
end

local function phone_anim_restart(ped)
    local now = util.current_time_millis()
    if now - phone_anim.last_restart < phone_anim.cooldown then return end
    if native.get_number_of_threads_running_the_script_with_this_hash(phone_anim_hash()) ~= 0 then return end

    phone_anim.last_restart = now
    phone_anim_set_flags(ped, true)
    native_call(native.destroy_mobile_phone)
    yield_ms(120)

    if ped and ped ~= 0 and ENTITY.DOES_ENTITY_EXIST(ped) and not native.is_ped_in_any_vehicle(ped, true) then
        native_call(native.create_mobile_phone, 0)
        native_call(native.set_mobile_phone_scale, 300.0)
    end
end

favorites:toggle("Phone animations (online)")
    :tooltip("Use the online phone pull-out animation.")
    :event(menu.event.click, function(opt)
        phone_anim.enabled = opt and opt.value == true
        if not phone_anim.enabled then
            phone_anim_cleanup()
            return
        end
        if phone_anim.running then return end

        phone_anim.running = true
        util.create_job(function()
            while phone_anim.enabled do
                local ped = ensure_ped()
                if ped and ped ~= 0 and ENTITY.DOES_ENTITY_EXIST(ped) and not native.is_entity_dead(ped) and not native.is_ped_in_any_vehicle(ped, true) then
                    phone_anim_set_flags(ped, true)
                    phone_anim_restart(ped)
                    if PED and PED.IS_PED_RUNNING_MOBILE_PHONE_TASK then
                        local running = PED.IS_PED_RUNNING_MOBILE_PHONE_TASK(ped)
                        if not running then native_call(native.task_use_mobile_phone, ped, true, 0) end
                    else
                        native_call(native.task_use_mobile_phone, ped, true, 0)
                    end
                end
                yield_ms(0)
            end
            phone_anim_cleanup()
            phone_anim.running = false
        end)
    end)

