function add_button_with_hotkey(
    list,
    label,
    handler,
    opts
)

    local remember_last = true

    if opts and opts.remember ~= nil then
        remember_last = opts.remember
    end

    local btn =
        list:button(label)


    if opts
    and opts.desc
    and btn.tooltip then

        btn:tooltip(opts.desc)
    end

    if btn.flags then

        btn:flags(menu.flags.hotkey)
    end

    btn:event(
        menu.event.click,

        function()

            run_handler(
                label,
                handler,
                remember_last
            )
        end
    )
end
