function add_dance_series(
    list,
    label_prefix,
    dict,
    anim_prefix,
    sets,
    gender
)

    local gender_suffix =
        gender or "female"

    local idx = 1

    for _, set in ipairs(sets) do

        local count =
            set.count or 6

        for _, variant
        in ipairs(set.variants) do

            for i = 1, count do

                local anim

                if set.prefix then

                    anim = string.format(
                        "%s_%s_%02d_%s_%s^%d",

                        anim_prefix,
                        set.prefix,
                        set.id,
                        variant,
                        gender_suffix,
                        i
                    )

                else

                    anim = string.format(
                        "%s_%02d_%s_%s^%d",

                        anim_prefix,
                        set.id,
                        variant,
                        gender_suffix,
                        i
                    )
                end

                add_emote(

                    list,

                    string.format(
                        "%s %02d",
                        label_prefix,
                        idx
                    ),

                    dict,
                    anim,
                    "stationary"
                )

                idx = idx + 1
            end
        end
    end
end
