DETACH_ENTITY               = 0x961AC54BF0613F5D
SET_ENTITY_COORDS_NO_OFFSET = 0x239A3351AC1DA385
DOES_ENTITY_EXIST           = 0x7239B21A38F536BA

function sink_entity(entity)

    if not entity
    or entity == 0 then
        return true
    end

    if not invoke(
        DOES_ENTITY_EXIST,
        entity
    ).bool then
        return true
    end
    local timeout = 0

        while invoke(NETWORK_HAS_CONTROL_OF_ENTITY, entity).bool == false
        and timeout < 20 do

            invoke(NETWORK_REQUEST_CONTROL, entity)

            timeout = timeout + 1

            yield_ms(0)
        end

        invoke(
            SET_ENTITY_AS_MISSION_ENTITY,
            entity,
            true,
            true
        )

        invoke(
            DETACH_ENTITY,
            entity,
            true,
            true
        )

        invoke(
            DELETE_ENTITY,
            entity
        )

        native.delete_entity(entity)

        if invoke(
            DOES_ENTITY_EXIST,
            entity
        ).bool then

            invoke(
                SET_ENTITY_COORDS_NO_OFFSET,

                entity,

                0.0,
                0.0,
                -1000.0,

                true,
                true,
                true
            )

            invoke(
                SET_ENTITY_AS_MISSION_ENTITY,
                entity,
                true,
                true
            )

            invoke(
                DELETE_ENTITY,
                entity
            )

            native.delete_entity(entity)
        end

        if invoke(
            DOES_ENTITY_EXIST,
            entity
        ).bool then

            native.delete_entity(entity)
        end

    return not invoke(
        DOES_ENTITY_EXIST,
        entity
    ).bool
end
function detach_tracked()

    if not attached_objects
    or next(attached_objects) == nil then
        return
    end

    for obj in pairs(attached_objects) do

        sink_entity(obj)
    end

    attached_objects = {}
end
function attach_all(
    items,
    clear_existing
)

    if not items then
        return 0
    end
    local prepared = {}

    for _, i in ipairs(items) do

        if i then

            local v =
                validate_attachment(i)

            if v then

                local loaded_hash = request_attachment_model(v.hash)

                if loaded_hash then
                    v.hash = loaded_hash

                    prepared[
                        #prepared + 1
                    ] = v

                else

                    log_warn(
                        string.format(
                            "attach_all: model load failed hash=%s",
                            tostring(v.hash)
                        )
                    )
                end

            else

                log_warn(
                    "attach_all: invalid attachment skipped"
                )
            end
        end
    end
    if #prepared == 0 then

        log_attach(
            "attach_all: no valid attachments; skip detach"
        )

        return 0
    end
    if clear_existing then
        detach_tracked()
    end
    local attached = 0

    for _, v in ipairs(prepared) do

        local obj = attach_prop(

            v.hash,
            v.bone,

            v.offx,
            v.offy,
            v.offz,

            v.rotx,
            v.roty,
            v.rotz,

            true
        )

        if obj then
            attached = attached + 1
        end
    end

    return attached
end
function attach_clipboard_and_pen(
    clear_existing
)

    attach_all(

        {
            PROPS.CLIPBOARD,
            PROPS.PEN
        },

        clear_existing or false
    )
end

function attach_glow_sticks(
    clear_existing
)

    attach_all(

        {
            PROPS.GLOW_STICK_R,
            PROPS.GLOW_STICK_L
        },

        clear_existing or false
    )
end

function attach_all_with_warn(
    items,
    label,
    clear_existing
)

    local count = attach_all(
        items,
        clear_existing
    )

    if items and count == 0 then

        local name =
            label or "action"

        log_attach(
            string.format(
                "No attachments created (%s)",
                tostring(name)
            )
        )

        notify_attach(
            string.format(
                "No props attached (%s)",
                tostring(name)
            )
        )
    end

    return count
end

function run_anim_cfg(cfg)

    if not cfg then
        return
    end

    if cfg[1]
    and (cfg[1].dict or cfg[1].scenario) then

        for _, c in ipairs(cfg) do
            run_anim_cfg(c)
        end

        return
    end
    if cfg.scenario then

        start_scenario(
            cfg.scenario
        )

    else

        play_emote(

            cfg.dict,
            cfg.anim or cfg.name,
            cfg.mode
        )
    end
end
function add_prop_action(
    list,
    label,
    attachments,
    anim
)

    add_button_with_hotkey(

        list,
        label,

        function()

            attach_all_with_warn(
                attachments,
                label
            )

            if anim
            and (
                anim.dict
                or anim.anim
                or anim.scenario
            ) then

                run_anim_cfg(anim)
            end
        end
    )
end
function normalize_item(item)

    if not item then
        return nil
    end
    if type(item) == "table"
    and item.label
    and (
        item.dict
        or item.scenario
        or item.attachments
    ) then

        return item
    end
    if type(item) == "table"
    and (
        item.dict
        or item.scenario
        or item.handler
        or item.attachments
        or item.label
    ) then

        local label =
            trim(item.label)

        local dict =
            item.dict
            and trim(item.dict)
            or nil

        local anim =
            item.anim or item.name

        if type(anim) == "string" then
            anim = trim(anim)
        end

        local mode =
            item.mode
            and trim(item.mode)
            or nil

        local scenario =
            item.scenario
            and trim(item.scenario)
            or nil
        if not validate_item_fields(
            label,
            dict,
            anim,
            mode,
            scenario
        ) then

            log_warn(
                "normalize_item: invalid item fields"
            )

            return nil
        end

        return {

            label = label,

            attachments =
                item.attachments,

            scenario =
                scenario ~= ""
                and scenario
                or nil,

            handler =
                item.handler,

            dict =
                dict ~= ""
                and dict
                or nil,

            anim =
                anim ~= ""
                and anim
                or nil,

            mode =
                mode ~= ""
                and mode
                or nil,
        }
    end
    if type(item) ~= "table" then
        return nil
    end

    local label =
        trim(item[1])

    local second = item[2]
    local third  = item[3]
    local fourth = item[4]

    local attachments
    local scenario
    local dict
    local anim
    local mode

    if type(second) == "table"
    and (
        second.hash
        or type(second[1]) == "table"
    ) then

        attachments = second

    elseif type(second) == "string" then

        dict = trim(second)
    end

    if type(third) == "string" then

        anim = trim(third)

    elseif type(third) == "table" then

        scenario =
            third.scenario
            or scenario

        dict =
            dict
            or third.dict
            or third[1]

        anim =
            anim
            or third.anim
            or third.name
            or third[2]

        mode =
            mode
            or third.mode
            or third[3]
    end

    if not mode
    and fourth
    and type(fourth) == "string" then

        mode = trim(fourth)
    end

    if type(scenario) == "string" then
        scenario = trim(scenario)
    end

    if type(dict) == "string" then
        dict = trim(dict)
    end

    if type(anim) == "string" then
        anim = trim(anim)
    end

    if type(mode) == "string" then
        mode = trim(mode)
    end

    if scenario == "" then
        scenario = nil
    end

    if dict == "" then
        dict = nil
    end

    if anim == "" then
        anim = nil
    end

    if mode == "" then
        mode = nil
    end

    if not validate_item_fields(
        label,
        dict,
        anim,
        mode,
        scenario
    ) then

        log_warn(

            string.format(
                "normalize_item: invalid array item (%s)",
                tostring(label)
            )
        )

        return nil
    end
    return {

        label = label,

        attachments =
            attachments,

        scenario =
            scenario,

        handler = nil,

        dict = dict,
        anim = anim,
        mode = mode,
    }
end
function register_items(
    menu_ref,
    data
)

    local seen = {}
    local seen_payload = {}

    local issues = 0

    for _, raw in ipairs(data) do

        local item =
            normalize_item(raw)

        local label =
            item and trim(item.label)

        if not label then
            goto continue
        end

        local key =
            label:lower()
        if seen[key] then

            log_warn(

                string.format(
                    "Skip duplicate label: %s",
                    tostring(label)
                )
            )

            issues = issues + 1

            goto continue
        end

        seen[key] = true
        local has_payload =

            item.scenario
            or item.attachments
            or (item.dict and item.anim)
            or item.handler

        if not has_payload then

            log_warn(

                string.format(
                    "Skip empty item (need dict/anim/attachments/scenario): %s",
                    tostring(label)
                )
            )

            goto continue
        end

        if item.dict
        and item.anim
        and not item.attachments
        and not item.scenario
        and not item.handler then

            local payload_key =
                string.format(
                    "%s|%s|%s",

                    item.dict,
                    item.anim,
                    item.mode or ""
                )

            if seen_payload[payload_key] then

                log_warn(

                    string.format(
                        "Skip duplicate anim entry: %s (%s)",
                        tostring(label),
                        tostring(payload_key)
                    )
                )

                issues = issues + 1

                goto continue
            end

            seen_payload[payload_key] = true
        end
        if item.handler then

            add_button_with_hotkey(

                menu_ref,
                label,
                item.handler
            )

        elseif item.scenario then

            add_scenario(

                menu_ref,
                label,
                item.scenario
            )

        elseif item.attachments
        or not item.dict then

            local anim_payload

            if item.dict
            or item.anim
            or item.mode then

                anim_payload = {

                    dict = item.dict,
                    anim = item.anim,
                    mode = item.mode
                }
            end

            add_prop_action(

                menu_ref,
                label,
                item.attachments,
                anim_payload
            )

        else

            add_emote(

                menu_ref,

                label,

                item.dict,
                item.anim,
                item.mode
            )
        end

        ::continue::
    end

    if issues > 0 then

        log_warn(

            string.format(
                "register_items: validation skipped %d entries",
                tonumber(issues)
            )
        )
    end
end

function register_emotes(
    menu_ref,
    data
)

    register_items(
        menu_ref,
        data
    )
end

