animuwu_network_ptfx_entity = nil

function animuwu_model(value)
    if type(value) == "table" then
        if #value == 0 then return nil end
        return value[math.random(1, #value)]
    end
    return value
end

function animuwu_attach_prop(model, bone, placement)
    local ped = ensure_ped()
    if not ped then return nil end

    model = animuwu_model(model)
    local hash = type(model) == "number" and model or cx_hash(model)
    hash = request_attachment_model(hash)
    if not hash then return nil end

    local x, y, z = Natives.InvokeV3(GET_ENTITY_COORDS, ped, true)
    local object, created_hash = create_attachment_object(hash, x, y, z + 0.2)
    if not object or object == 0 then return nil end

    placement = placement or {}
    local bone_index = Natives.InvokeInt(GET_PED_BONE_INDEX, ped, tonumber(bone) or 28422)

    Natives.InvokeVoid(
        ATTACH_ENTITY_TO_ENTITY,
        object,
        ped,
        bone_index,
        placement[1] or 0.0,
        placement[2] or 0.0,
        placement[3] or 0.0,
        placement[4] or 0.0,
        placement[5] or 0.0,
        placement[6] or 0.0,
        true,
        true,
        false,
        true,
        1,
        true
    )

    attached_objects[object] = true
    Natives.InvokeVoid(SET_MODEL_AS_NO_LONGER_NEEDED, created_hash or hash)
    return object
end

function animuwu_flags(options)
    if not options then return 0 end

    if options.EmoteLoop then
        if options.EmoteMoving then return 51 end
        return 1
    end
    if options.EmoteMoving then return 51 end
    if options.EmoteMoving == false then return 0 end
    if options.EmoteStuck then return 50 end
    return 0
end

function animuwu_play_prop_emote(emote)
    local options = emote.AnimationOptions or {}
    local dict = emote[1]
    local anim = emote[2]
    local ped = ensure_ped()
    if not ped or not ensure_anim_dict(dict) then return end

    if not animuwu_keep_objects_on_change then
        if options.PtfxNetworked and clear_camera_objects then
            clear_camera_objects()
        else
            detach_tracked()
        end
    end
    animuwu_network_ptfx_entity = nil
    native.task_play_anim(
        ped,
        dict,
        anim,
        2.0,
        2.0,
        tonumber(options.EmoteDuration) or -1,
        animuwu_flags(options),
        0.0,
        false,
        false,
        false
    )

    local wait = tonumber(options.EmoteDuration) or 0
    if wait > 0 then Script.Yield(wait) end

    local primary_prop = animuwu_attach_prop(options.Prop, options.PropBone, options.PropPlacement)
    if options.PtfxNetworked and options.PtfxName and primary_prop then
        animuwu_network_ptfx_entity = primary_prop
        safe_notify("Camera", "Press G to use the networked flash")
    end
    if options.SecondProp then
        animuwu_attach_prop(options.SecondProp, options.SecondPropBone, options.SecondPropPlacement)
    end
end

function register_animuwu_props()
    local labels = {}

    for index, emote in ipairs(animuwu_prop_emotes) do
        if emote.Command ~= "crouch_movement" then
            local label = emote[3] or ("2AnimUwU Prop " .. tostring(index))
            local key = tostring(label):lower()
            if labels[key] then
                labels[key] = labels[key] + 1
                label = label .. " (" .. tostring(labels[key]) .. ")"
            else
                labels[key] = 1
            end

            local data = emote
            add_button_with_hotkey(animuwu_props, label, function()
                animuwu_play_prop_emote(data)
            end)
        end
    end
end

register_animuwu_props()


