local function kscript_attachment(model, bone, placement)
    placement = placement or {}
    return {
        hash = model,
        bone = bone,
        offx = placement[1] or 0.0,
        offy = placement[2] or 0.0,
        offz = placement[3] or 0.0,
        rotx = placement[4] or 0.0,
        roty = placement[5] or 0.0,
        rotz = placement[6] or 0.0,
    }
end

local function kscript_mode(options)
    if options and options.EmoteMoving then
        return "moving"
    end
    if options and options.EmoteLoop then
        return "stationary"
    end
    return "once"
end

local function register_kscript_emotes(menu_ref, catalog)
    local entries = {}

    for key, emote in pairs(catalog) do
        local options = emote.AnimationOptions or {}
        local item = {
            label = emote[3] or key,
            mode = kscript_mode(options),
        }

        if emote[1] == "Scenario" or emote[1] == "MaleScenario" then
            item.scenario = emote[2]
        else
            item.dict = emote[1]
            item.anim = emote[2]
        end

        if options.Prop then
            item.attachments = {
                kscript_attachment(options.Prop, options.PropBone, options.PropPlacement)
            }

            if options.SecondProp then
                item.attachments[#item.attachments + 1] =
                    kscript_attachment(options.SecondProp, options.SecondPropBone, options.SecondPropPlacement)
            end
        end

        entries[#entries + 1] = item
    end

    table.sort(entries, function(a, b)
        return tostring(a.label):lower() < tostring(b.label):lower()
    end)

    register_items(menu_ref, entries)
end

register_kscript_emotes(misc, kscript_emotes)
register_kscript_emotes(dances, kscript_dances)
register_kscript_emotes(props, kscript_props)
register_kscript_emotes(romance, kscript_naughty)


