    submenu,
    label,
    clipset
)

    submenu:button(label)
    :event(menu.event.click, function()


        invoke(
            0x6D9F5FAA7488BA46,
            clipset
        )

        while not invoke(
            0xD031A9162D01088C,
            clipset
        ).bool do

            Script.Yield(0)
        end

        invoke(
            0xAF8A94EDE7712BEF,
            get_ped(),
            clipset,
            1.0
        )

        safe_notify(
            "Meow Emotes",
            label .. " Applied!"
        )
    end)
end


