function clear_all_attached_to_me()

    local ped = native.player_ped_id()

    if not ped or ped == 0 then
        return
    end

    if native.does_entity_exist and not native.does_entity_exist(ped) then
        return
    end
    local objects = {}

        for obj in pairs(attached_objects or {}) do

            sink_entity(obj)
        end

        attached_objects = {}


        if entities and entities.get_all_objects then

            objects = entities.get_all_objects()

        elseif pools and pools.object then

            objects = pools.object()

        elseif pools and pools.get_all_objects then

            objects = pools.get_all_objects()

        end

        for _, handle in ipairs(objects) do

            if handle
            and handle ~= 0
            and native.does_entity_exist(handle) then

                local attached_to =
                    invoker.call(
                        0x48C2BED9180FE123,
                        handle
                    ).int

                if attached_to == ped then
                    sink_entity(handle)
                end
            end
        end

    native.clear_ped_tasks_immediately(ped)

    safe_notify(
        "Cleanup",
        "All attached objects removed"
    )
end

function cleanup()
    detach_tracked()

        local cached_models = {}

        for hash in pairs(model_cache or {}) do
            cached_models[#cached_models + 1] = hash
        end

        local cached_dicts = {}

        for dict in pairs(anim_dict_cache or {}) do
            cached_dicts[#cached_dicts + 1] = dict
        end

        attached_objects = {}
        model_cache = {}
        anim_dict_cache = {}
        resolved_anim_cache = {}

        for _, hash in ipairs(cached_models) do

            if native.set_model_as_no_longer_needed then
                native.set_model_as_no_longer_needed(hash)
            end
        end

        for _, dict in ipairs(cached_dicts) do

            if native.remove_anim_dict then
                native.remove_anim_dict(dict)
            end
        end

        local ped = ensure_ped()

        if ped and ped ~= 0 then

            if native.clear_ped_tasks_immediately then
                native.clear_ped_tasks_immediately(ped)
            elseif native.clear_ped_tasks then
                native.clear_ped_tasks(ped)
            end
        end

        collectgarbage("collect")

        safe_notify(
            "Cleanup",
            "Emote cache cleaned"
        )

        log_tag(
            "Cleanup",
            "Manual cleanup completed"
        )
end

