RING_PROP = -1407761612

function run_kneel_proposal()
	local ped = ensure_ped()
	if not ped then return end

	if not request_model(RING_PROP) then
		safe_notify("Emotes", "Proposal prop load failed")
		return
	end

	local kneel_dict = "amb@medic@standing@kneel@base"
	local hand_dict = "anim@weapons@flashlight@"
	cx_native.request_anim_dict(kneel_dict)
	cx_native.request_anim_dict(hand_dict)
	while not cx_native.has_anim_dict_loaded(kneel_dict) or not cx_native.has_anim_dict_loaded(hand_dict) do
		yield_ms(0)
	end

	native.task_play_anim(ped, kneel_dict, "base", 3.0, 2.0, -1, ANIM_FLAG.STATIONARY, 0.0, false, 0, false)
	yield_ms(120)
	native.task_play_anim(ped, hand_dict, "aim_high_loop", 3.0, 2.0, -1, DEFAULT_TASK_FLAGS, 0.0, false, 0, false)
	yield_ms(120)
	attach_prop(RING_PROP, BONE.RIGHT_HAND, 0.048, 0.105, 0.013, -10.0, -90.0, -140.0)
end

