cat_tools = emotes:submenu("Cat Animations")
cat_entity = 0

function meow_create_ped(ped_type, hash, x, y, z, heading)
    local created = GTA.CreatePed(hash, ped_type or 28, x, y, z, heading or 0.0, true, true)
    if type(created) == "number" then return created end
    if GTA and GTA.PointerToHandle then return GTA.PointerToHandle(created) or 0 end
    return 0
end

function meow_create_object(hash, x, y, z)
    return GTA.CreateObject(hash, x, y, z, true, true)
end

function meow_attach_entity_to_entity(entity, target, bone, offx, offy, offz, rotx, roty, rotz)
    Natives.InvokeVoid(SET_ENTITY_AS_MISSION_ENTITY, entity, true, true)
    Natives.InvokeVoid(
        ATTACH_ENTITY_TO_ENTITY,
        entity,
        target,
        bone,
        offx or 0.0,
        offy or 0.0,
        offz or 0.0,
        rotx or 0.0,
        roty or 0.0,
        rotz or 0.0,
        true,
        true,
        false,
        true,
        1,
        true,
        false
    )
end

function meow_set_entity_coords(entity, x, y, z)
    Natives.InvokeVoid(0x06843DA7060A026B, entity, x, y, z, false, false, false, true)
end

function meow_cat_anim(ped, dict, name)
    native.request_anim_dict(dict)
    local deadline = native.get_game_timer() + 5000
    while not native.has_anim_dict_loaded(dict) do
        if native.get_game_timer() >= deadline then
            safe_notify("Cat Animations", "Cat animation could not be loaded.")
            return false
        end
        native.request_anim_dict(dict)
        Script.Yield(0)
    end
    native.task_play_anim(ped, dict, name, 4.0, 4.0, -1, 49, 0.0, false, false, false)
    return true
end

function meow_delete_cat()
    if not cat_entity or cat_entity == 0 then return end
    if native.does_entity_exist(cat_entity) then
        native.detach_entity(cat_entity, true, true)
        native.clear_ped_tasks(cat_entity)
        native.clear_ped_secondary_task(cat_entity)
        for _ = 1, 20 do
            if native.network_has_control_of_entity(cat_entity) then break end
            native.network_request_control_of_entity(cat_entity)
            Script.Yield(0)
        end
        native.set_entity_as_mission_entity(cat_entity, true, true)
        local pointer = Memory.AllocInt()
        Memory.WriteInt(pointer, cat_entity)
        Natives.InvokeVoid(0x9614299DCB53E54B, pointer)
        Memory.Free(pointer)
    end
    cat_entity = 0
end

function spawn_and_pickup_cat()
    local ped = players.me().ped
    if not ped or ped == 0 then return end

    if cat_entity and cat_entity ~= 0 and native.does_entity_exist(cat_entity) then
        meow_delete_cat()
    end

    local hash = cx_hash("a_c_cat_01")
    if not request_model(hash) then return end

    local x, y, z = Natives.InvokeV3(GET_ENTITY_COORDS, ped, true)
    cat_entity = meow_create_ped(28, hash, x, y + 0.6, z, 0.0) or 0
    if cat_entity == 0 or not native.does_entity_exist(cat_entity) then
        cat_entity = 0
        safe_notify("Cat Animations", "Cat could not be spawned.")
        return
    end

    native.set_entity_as_mission_entity(cat_entity, true, true)
    native.set_blocking_of_non_temporary_events(cat_entity, true)
    native.set_ped_can_ragdoll(cat_entity, false)

    local dict = "anim@scripted@freemode@ig1_pickup_cat@male@"
    if not meow_cat_anim(ped, dict, "pick_up_facing_away_player") then
        meow_delete_cat()
        return
    end
    Script.Yield(4000)

    local hand = native.get_ped_bone_index(ped, 57005)
    set_cat_pickup_state(cat_entity, true)
    meow_attach_entity_to_entity(cat_entity, ped, hand, 0.10, 0.00, -0.10, 0.0, 200.0, 30.0)
    set_cat_pickup_state(cat_entity, true)
    meow_cat_anim(ped, dict, "idle_player")
end

function place_cat()
    local ped = players.me().ped
    if not cat_entity or cat_entity == 0 or not native.does_entity_exist(cat_entity) then return end

    local dict = "anim@scripted@freemode@ig1_pickup_cat@male@"
    meow_cat_anim(ped, dict, "put_down_exit_player")
    Script.Yield(5000)

    native_call(native.detach_entity, cat_entity, true, true)
    set_cat_pickup_state(cat_entity, false)

    local x, y, z = Natives.InvokeV3(GET_ENTITY_COORDS, ped, true)
    meow_set_entity_coords(cat_entity, x, y + 0.5, z)
    native_call(native.clear_ped_tasks, ped)
end

