    "prop_prlg_gravestone_01a",
    "prop_prlg_gravestone_02a",
    "prop_prlg_gravestone_03a",
    "prop_prlg_gravestone_04a",
    "prop_prlg_gravestone_05a",
    "prop_prlg_gravestone_06a",
    "prop_gravestones_05a",
    "prop_gravestones_06a",
    "prop_gravestones_07a",
    "test_prop_gravestones_07a",
}
grave_setting = {
    enabled = false,
    delete_last = false,
    blip = false,
    explosion = true,
    hash = cx_hash(grave_models[1]),
    done = false,
    last = 0,
    spawned = {},
}

function grave_set_model(model)
    grave_setting.hash = cx_hash(model)
    safe_notify("Gravestones", model)
end

function grave_delete(entity)
    if entity and entity ~= 0 then
        sink_entity(entity)
    end
end

function grave_position()
    local me = players.me()
    if invoker and invoker.call then
        local pos = invoker.call(0xCD5003B097200F36, me.ped, 0.5, 1.5).scr_vec3
        if pos then return pos end
    end
    return me.coords
end

function grave_add_explosion(pos)
    if not grave_setting.explosion or not pos then return end
    if invoker and invoker.call and scr_vec3 then
        local v = scr_vec3()
        v.x = pos.x
        v.y = pos.y
        v.z = pos.z
        local ok = invoker_call(0xE3AD2BDBAEE269AC, v, 4, 0.0, true, false, 1.0, true)
        if ok then return end
    end
    invoker_call(0xE3AD2BDBAEE269AC, pos.x, pos.y, pos.z, 4, 0.0, true, false, 1.0, true)
end

function spawn_gravestone_obj(from_death)
    local me = players.me()
    if from_death and not grave_setting.enabled then return end
    if not me or not me.ped or me.ped == 0 then return end
    if not request_model(grave_setting.hash) then return end

    local pos = grave_position()
    local obj = meow_create_object(grave_setting.hash, pos.x, pos.y, pos.z)
    if not obj or obj == 0 then return end

    native_call(native.set_entity_heading, obj, me.heading or 0.0)
    native_call(native.set_entity_invincible, obj, true)
    native_call(native.set_entity_no_collision_entity, me.ped, obj, true)
    invoker_call(0xD76EEEF746057FD6, obj)
    invoker_call(0x58A850EAEE20FAA3, obj)

    if grave_setting.blip and invoker and invoker.call then
        local blip = invoker_int(0x5CDE92C702A8FCE7, obj)
        if blip and blip ~= 0 then
            invoker_call(0xDF735600A4696DAF, blip, 274)
            invoker_call(0xD38744167B2FA257, blip, 0.6)
        end
    end

    grave_setting.spawned[#grave_setting.spawned + 1] = obj
    if grave_setting.delete_last and grave_setting.last ~= 0 then
        grave_delete(grave_setting.last)
    end
    grave_setting.last = obj
    grave_add_explosion(pos)
end

util.create_thread(function()
    if not grave_setting.enabled or not game.in_game() then return end

    local me = players.me()
    if me and me.alive == false then
        if not grave_setting.done then
            grave_setting.done = true
            util.create_job(function() spawn_gravestone_obj(true) end)
        end
    else
        grave_setting.done = false
    end
end)

