tattoo_add_one = tattoo_tools:submenu("Add Tattoo")
tattoo_delete_one = tattoo_tools:submenu("Delete Tattoo")

function tattoo_is_mpply(stat)
    if stat == "MP_PLAYING_TIME" then return true end
    return tostring(stat):find("MPPLY_", 1, true) ~= nil
end

function tattoo_add_mp_index(stat)
    if tattoo_is_mpply(stat) then return stat end
    local slot = 0
    if util.get_char_slot then
        slot = util.get_char_slot()
    elseif account and account.character then
        slot = account.character()
    end
    return "MP" .. tostring(slot or 0) .. "_" .. tostring(stat)
end

function tattoo_stat_set_int(stat, value)
    local name = tattoo_add_mp_index(stat)

    if account and account.stats then
        account.stats(name).int32 = value
        return true
    end

    if STATS and STATS.STAT_SET_INT then
        STATS.STAT_SET_INT(cx_hash(name), value, true)
        return true
    end

    if invoker and invoker.call then
        invoker.call(0xB3271D7AB655B441, cx_hash(name), value, true)
        return true
    end

    return false
end

function tattoo_set_range(first, last, value)
    for index = first, last do
        tattoo_stat_set_int("TATTOO_FM_CURRENT_" .. tostring(index), value)
    end
end

function tattoo_notify_set()
    safe_notify("Tattoos", "Change session to set tattoos")
end

function tattoo_notify_delete()
