function set_walk_style(clipset)
    local ped = get_ped()
    if ped == 0 or ped == nil then return end

    if clipset == "reset" then
        native.reset_ped_movement_clipset(ped, 0.0)
    else
        cx_native.request_anim_set(clipset)
        local timeout = os.time() + 2
        while not cx_native.has_anim_set_loaded(clipset) do
            if os.time() > timeout then break end
            yield(0)
        end
        native.set_ped_movement_clipset(ped, clipset, 0.0)
    end
end

