MyMod = {
    disableHotKeys = false,
    xstate = false,
    native = native
}

function MyMod.dictLoad(dict)
    native_call(MyMod.native.request_anim_dict, dict)
    local tries = 0
    while not MyMod.native.has_anim_dict_loaded(dict) and tries < 100 do
        util.yield(10)
        tries = tries + 1
    end
end

function MyMod.dictUnload(dict)
    native_call(MyMod.native.remove_anim_dict, dict)
end

function MyMod.animPlay(dict, name, duration, flags, hped)
    duration = duration or -1
    flags = flags or 51
    MyMod.dictLoad(dict)
    hped = hped or players.me().ped
    native_call(MyMod.native.task_play_anim, hped, dict, name, 4.0, 4.0, duration, flags, 0, false, false, false)
end

function MyMod.animStop()
    local ped = players.me().ped
    native_call(MyMod.native.clear_ped_tasks, ped)
    native_call(MyMod.native.clear_ped_secondary_task, ped)
    native_call(MyMod.native.give_weapon_to_ped, ped, MyMod.native.get_hash_key("WEAPON_UNARMED"), 1, false, true)
end

