hotkeys_menu:toggle("Disable X key")
    :flags(menu.flags.hotkey)
    :event(menu.event.click, function(opt)
        MyMod.disableHotKeys = opt.value
    end)

util.create_thread(function()
    local KEY_X = 0x58
    while true do
        local isPressed = false
        if Utils and Utils.IsKeyDown then
            isPressed = Utils.IsKeyDown(KEY_X)
        elseif input and input.key then
            local keyState = input.key(KEY_X)
            isPressed = keyState and keyState.pressed or false
        end

        if not MyMod.disableHotKeys and isPressed and not MyMod.xstate then
            MyMod.xstate = true
            MyMod.animPlay("random@mugging3", "handsup_standing_base", -1, 51)
        elseif (MyMod.disableHotKeys or not isPressed) and MyMod.xstate then
            MyMod.xstate = false
            MyMod.animStop()
        end

        util.yield(10)
    end
end)

