local meow_attach_debug_enabled = false
local meow_attach_debug_path = ((_G and _G.MeowPartyStorageDir) or "") .. "MeowAttachDebug.txt"
local function meow_attach_debug(msg)
    if not meow_attach_debug_enabled or not io or not io.open then return end
    local file = io.open(meow_attach_debug_path, "a")
    if file then
        file:write(os.date("%Y-%m-%d %H:%M:%S") .. " " .. tostring(msg) .. "\n")
        file:close()
    end
end

do
local __meow_attach_clock_start = os.clock()
local __meow_attach_feature_counter = 0
local __meow_attach_roots = {}

local function __meow_attach_log(message)
    if Logger and Logger.LogInfo then
        Logger.LogInfo(tostring(message))
    else
        print(tostring(message))
    end
end

local function __meow_attach_notify(title, message)
    title = tostring(title or "Meow Attach")
    message = tostring(message or "")
    if GUI and GUI.AddToast then
        GUI.AddToast(title, message, 5000, eToastPos.TOP_RIGHT)
    else
        __meow_attach_log(title .. ": " .. message)
    end
end

local function __meow_attach_vec3(x, y, z)
    local value = { x = x or 0.0, y = y or 0.0, z = z or 0.0 }
    function value:distance3d(other)
        other = other or { x = 0.0, y = 0.0, z = 0.0 }
        local dx = (self.x or 0.0) - (other.x or 0.0)
        local dy = (self.y or 0.0) - (other.y or 0.0)
        local dz = (self.z or 0.0) - (other.z or 0.0)
        return math.sqrt(dx * dx + dy * dy + dz * dz)
    end
    return value
end

local function __meow_attach_native_vec3(hash, ...)
    local x, y, z = Natives.InvokeV3(hash, ...)
    return __meow_attach_vec3(x, y, z)
end

local function __meow_attach_handle(value)
    if value == nil then return 0 end
    if type(value) == "number" then return value end
    if GTA and GTA.PointerToHandle then
        local handle = GTA.PointerToHandle(value)
        if handle then return handle end
    end
    return 0
end

local function __meow_attach_player(player_id)
    player_id = player_id or GTA.GetLocalPlayerId()
    local ped = 0
    if Players and Players.GetCPed then ped = __meow_attach_handle(Players.GetCPed(player_id)) end
    if ped == 0 and Players and Players.GetPed then ped = __meow_attach_handle(Players.GetPed(player_id)) end
    if ped == 0 and player_id == GTA.GetLocalPlayerId() then ped = __meow_attach_handle(GTA.GetLocalPed()) end

    local coords = __meow_attach_vec3(0.0, 0.0, 0.0)
    if ped ~= 0 then coords = __meow_attach_native_vec3(0x3FEF770D40960D5A, ped, false) end

    return {
        id = player_id,
        player = player_id,
        ped = ped,
        coords = coords,
        heading = ped ~= 0 and Natives.InvokeFloat(0xE83D4F9BA2A38914, ped) or 0.0,
        vehicle = ped ~= 0 and Natives.InvokeInt(0x9A9112A0FE9A4713, ped, false) or 0,
        exists = ped ~= 0,
        name = (Players and Players.GetName and Players.GetName(player_id)) or tostring(player_id)
    }
end

