CheraxMenu = CheraxMenu or { event = { click = 0 }, slider = { scroll = 0 } }

if not CheraxMenu.__meow_attach_wrapper then
    CheraxMenu.__meow_attach_wrapper = true

    local function __meow_attach_feature_option(feature, kind, list)
        return setmetatable({ list = list }, {
            __index = function(_, key)
                if key == "value" then
                    if kind == "toggle" then return feature:IsToggled() end
                    if kind == "combo" then return feature:GetListIndex() + 1 end
                    if kind == "number" then return feature:GetIntValue() end
                    if kind == "input" then return feature:GetStringValue() end
                    return nil
                end
            end,
            __newindex = function(_, key, value)
                if key == "value" then
                    if kind == "toggle" then feature:Toggle(value and true or false)
                    elseif kind == "combo" then feature:SetListIndex(math.max((value or 1) - 1, 0))
                    elseif kind == "number" then feature:SetIntValue(value or 0)
                    elseif kind == "input" then feature:SetStringValue(value or "") end
                else
                    rawset(_, key, value)
                end
            end
        })
    end

    local function __meow_attach_new_menu_node(label, parent)
        local node = { label = label, parent = parent, children = {}, features = {} }

        function node:submenu(name)
            local child = __meow_attach_new_menu_node(name, self)
            table.insert(self.children, child)
            return child
        end

        local function add_feature(kind, name, items, default_index)
            __meow_attach_feature_counter = __meow_attach_feature_counter + 1
            local hash = Utils.Joaat((node.label or "Meow Attach") .. "/" .. name .. "/" .. tostring(__meow_attach_feature_counter))
            local feature_type = eFeatureType.Button
            if kind == "toggle" then feature_type = eFeatureType.Toggle end
            if kind == "combo" then feature_type = eFeatureType.Combo end
            if kind == "number" then feature_type = eFeatureType.SliderInt end
            if kind == "input" then feature_type = eFeatureType.InputText end

            local wrapper = { hash = hash, callback = nil, feature = nil, kind = kind }
            local list_proxy = nil
            local feature = FeatureMgr.AddFeature(hash, name, feature_type, "", function(feature_instance)
                wrapper.feature = feature_instance
                if wrapper.callback then wrapper.callback(__meow_attach_feature_option(feature_instance, kind, list_proxy)) end
            end, true)
            wrapper.feature = feature

            if feature.SetNoCallbackOnSettingsLoad then feature:SetNoCallbackOnSettingsLoad(true) end
            if feature.SetSaveable then feature:SetSaveable(false) end
            if feature.SetSearchable then feature:SetSearchable(true) end
            local root_tab = ListGUI and ListGUI.GetRootTab and ListGUI.GetRootTab()
            if root_tab and root_tab.AddFeature then root_tab:AddFeature(hash) end
            if feature.RegisterCallbackTrigger and eCallbackTrigger and eCallbackTrigger.OnClick then
                feature:RegisterCallbackTrigger(eCallbackTrigger.OnClick)
            end

            if kind == "combo" then
                local display = {}
                list_proxy = { raw = items or {} }
                function list_proxy:at(index)
                    local item = self.raw[index]
                    if type(item) == "table" then return { name = item[1], value = item[2] } end
                    return { name = tostring(item), value = index }
                end
                for index, item in ipairs(items or {}) do
                    display[index] = type(item) == "table" and tostring(item[1]) or tostring(item)
                end
                feature:SetList(display)
                feature:SetListIndex(math.max((default_index or 1) - 1, 0))
            end

            if kind == "number" then feature:SetIntValue(0) end

            function wrapper:tooltip(desc)
                if self.feature and self.feature.SetDesc then self.feature:SetDesc(desc or "") end
                return self
            end

            function wrapper:fmt(fmt, min_value, max_value)
                if self.feature then
                    if self.feature.SetFormat and fmt then self.feature:SetFormat(fmt) end
                    if self.feature.SetLimitValues and min_value ~= nil and max_value ~= nil then self.feature:SetLimitValues(min_value, max_value) end
                    if self.feature.SetIntValue and min_value ~= nil then self.feature:SetIntValue(min_value) end
                end
                return self
            end

            function wrapper:step(value)
                if self.feature and self.feature.SetStepSize then self.feature:SetStepSize(value) end
                return self
            end

            function wrapper:event(_, callback)
                self.callback = callback
                return self
            end

            table.insert(node.features, wrapper)
            return wrapper
        end

        function node:button(name) return add_feature("button", name) end
        function node:toggle(name) return add_feature("toggle", name) end
        function node:combo_int(name, items, default_index) return add_feature("combo", name, items, default_index) end
        function node:number_int(name) return add_feature("number", name) end
        function node:input_text(name) return add_feature("input", name) end
        function node:textbox(name) return add_feature("input", name) end
        function node:string(name) return add_feature("input", name) end

        return node
    end

    local function __meow_attach_render_menu_node(node)
        for _, feature in ipairs(node.features) do
            if ClickGUI and ClickGUI.RenderFeature then ClickGUI.RenderFeature(feature.hash) end
        end
        for _, child in ipairs(node.children) do
            if ClickGUI and ClickGUI.BeginCustomChildWindow and ClickGUI.BeginCustomChildWindow(child.label) then
                __meow_attach_render_menu_node(child)
                if ClickGUI.EndCustomChildWindow then ClickGUI.EndCustomChildWindow() end
            end
        end
    end

    function CheraxMenu.meow_attach_root()
        if not __meow_attach_roots.root then
            __meow_attach_roots.root = __meow_attach_new_menu_node("Meow Attach")
            if ClickGUI and ClickGUI.AddTab then ClickGUI.AddTab("Meow Attach", function() __meow_attach_render_menu_node(__meow_attach_roots.root) end) end
        end
        return __meow_attach_roots.root
    end

    function CheraxMenu.meow_attach_player_root()
        if not __meow_attach_roots.player then
            __meow_attach_roots.player = __meow_attach_new_menu_node("Meow Attach Player")
            if ClickGUI and ClickGUI.AddPlayerTab then ClickGUI.AddPlayerTab("Meow Attach", function() __meow_attach_render_menu_node(__meow_attach_roots.player) end) end
        end
        return __meow_attach_roots.player
    end
end

