local function meow_party_storage_folder()
    local source = debug and debug.getinfo and debug.getinfo(1, "S").source
    if source and source:sub(1, 1) == "@" then
        local folder = source:sub(2):match("^(.*[\\/])")
        if folder and folder ~= "" then return folder end
    end

    if FileMgr and FileMgr.GetMenuRootPath then
        local root = FileMgr.GetMenuRootPath()
        if root and root ~= "" then
            local sep = root:sub(-1)
            if sep ~= "\\" and sep ~= "/" then root = root .. "\\" end
            return root .. "Lua\\"
        end
    end

    local one_drive = os and os.getenv and (os.getenv("OneDrive") or os.getenv("OneDriveConsumer"))
    if one_drive and one_drive ~= "" then return one_drive .. "\\Documentos\\Cherax\\Lua\\" end

    local user_profile = os and os.getenv and os.getenv("USERPROFILE")
    if user_profile and user_profile ~= "" then return user_profile .. "\\Documents\\Cherax\\Lua\\" end

    return ""
end

