local function hook_ride_find_bone(vehicle)
    local names = { "bonnet", "engine", "windscreen", "bumper_f", "chassis_dummy", "chassis" }
    local GET_ENTITY_BONE_INDEX_BY_NAME = 0xFB71170B7E76ACBA
    for _, name in ipairs(names) do
        local bone = -1
        if Natives and Natives.InvokeInt then
            bone = Natives.InvokeInt(GET_ENTITY_BONE_INDEX_BY_NAME, vehicle, name)
        elseif invoke then
            local res = invoke(GET_ENTITY_BONE_INDEX_BY_NAME, vehicle, name)
            bone = res and res.int or -1
        end
        if bone and bone ~= -1 then return bone, name end
    end
    return 0, "front hood offset"
end

