    if hood_up_slider and hood_up_slider.feature and hood_up_slider.feature.GetIntValue then hood_ride_up_cm = hood_up_slider.feature:GetIntValue() end
    if hood_use_presets_toggle and hood_use_presets_toggle.feature and hood_use_presets_toggle.feature.IsToggled then hood_ride_use_saved_presets = hood_use_presets_toggle.feature:IsToggled() end
end

