local function hood_ride_move(right, forward, up)
    hood_ride_right_cm = math.max(-1000, math.min(1000, hood_ride_right_cm + right))
    hood_ride_forward_cm = math.max(-1000, math.min(1000, hood_ride_forward_cm + forward))
    hood_ride_up_cm = math.max(-1000, math.min(1000, hood_ride_up_cm + up))
    hood_ride_set_slider_values()
    hood_ride_refresh()
end

