local function now_ms()
    return math.floor(os.clock() * 1000)
end

local function log(message)
    if Logger and Logger.LogInfo then
        Logger.LogInfo(SCRIPT_NAME .. ": " .. tostring(message))
    else
        print(SCRIPT_NAME .. ": " .. tostring(message))
    end
end

local function toast(message)
    if GUI and GUI.AddToast then
        GUI.AddToast(SCRIPT_NAME, tostring(message), 3000, eToastPos and eToastPos.TOP_RIGHT or 0)
    else
        log(message)
    end
end

local function ped_handle(value)
    if value == nil then return 0 end
    if type(value) == "number" then return value end
    if GTA and GTA.PointerToHandle then
        local handle = GTA.PointerToHandle(value)
        if handle then return handle end
    end
    return 0
end

local function local_ped()
    if PLAYER and PLAYER.PLAYER_PED_ID then
        local ped = PLAYER.PLAYER_PED_ID()
        if ped and ped ~= 0 then return ped end
    end

    if GTA and GTA.GetLocalPed then
        local ped_ptr = GTA.GetLocalPed()
        local ped = ped_handle(ped_ptr)
        if ped ~= 0 then return ped end
    end

    if GTA and GTA.GetLocalPlayerId and PLAYER and PLAYER.GET_PLAYER_PED_SCRIPT_INDEX then
        local player_id = GTA.GetLocalPlayerId()
        if player_id ~= nil then
            local ped = PLAYER.GET_PLAYER_PED_SCRIPT_INDEX(player_id)
            if ped and ped ~= 0 then return ped end
        end
    end

    return 0
end

local function entity_exists(entity)
    if entity == nil or entity == 0 then return false end
    if ENTITY and ENTITY.DOES_ENTITY_EXIST then
        return ENTITY.DOES_ENTITY_EXIST(entity) == true
    end
    return true
end

local function invoke_void(hash, ...)
    if not (Natives and Natives.InvokeVoid) then return false end
    Natives.InvokeVoid(hash, ...)
    return true
end

local function invoke_int(hash, ...)
    if not (Natives and Natives.InvokeInt) then return nil end
    return Natives.InvokeInt(hash, ...)
end

local function clear_ped_damage(ped)
    if PED and PED.RESET_PED_VISIBLE_DAMAGE then
        PED.RESET_PED_VISIBLE_DAMAGE(ped)
    else
        invoke_void(0x3AC1F7B898F30C05, ped)
    end
    if PED and PED.CLEAR_PED_BLOOD_DAMAGE then
        PED.CLEAR_PED_BLOOD_DAMAGE(ped)
    else
        invoke_void(0x8FE22675A5A45817, ped)
    end
    if PED and PED.CLEAR_PED_LAST_DAMAGE_BONE then
        PED.CLEAR_PED_LAST_DAMAGE_BONE(ped)
    else
        invoke_void(0x8EF6B7AC68E2F01B, ped)
    end
    for zone = 0, 5 do
        if PED and PED.CLEAR_PED_DAMAGE_DECAL_BY_ZONE then
            PED.CLEAR_PED_DAMAGE_DECAL_BY_ZONE(ped, zone, "ALL")
            PED.CLEAR_PED_DAMAGE_DECAL_BY_ZONE(ped, zone, "bruise")
            PED.CLEAR_PED_DAMAGE_DECAL_BY_ZONE(ped, zone, "bruise_large")
        else
            invoke_void(0x523C79AEEFCC4A2A, ped, zone, "ALL")
            invoke_void(0x523C79AEEFCC4A2A, ped, zone, "bruise")
            invoke_void(0x523C79AEEFCC4A2A, ped, zone, "bruise_large")
        end

        if PED and PED.CLEAR_PED_BLOOD_DAMAGE_BY_ZONE then
            PED.CLEAR_PED_BLOOD_DAMAGE_BY_ZONE(ped, zone)
        else
            invoke_void(0x56E3B78C5408D9F4, ped, zone)
        end
    end
end

local function clamp_int(value, min_value, max_value)
    value = tonumber(value) or min_value
    value = math.floor(value)
    if value < min_value then return min_value end
    if value > max_value then return max_value end
    return value
end

local function get_feature_string(feature, hash, default_value)
    if feature and feature.GetStringValue then
        local value = feature:GetStringValue()
        if value ~= nil then return tostring(value) end
    end

    if FeatureMgr and FeatureMgr.GetFeatureString then
        local value = FeatureMgr.GetFeatureString(hash)
        if value ~= nil then return tostring(value) end
    end

    return default_value or ""
end

local function set_feature_string(feature, hash, value)
    value = tostring(value or "")

    if feature and feature.SetStringValue then
        feature:SetStringValue(value)
    end

    if FeatureMgr and FeatureMgr.SetFeatureString then
        FeatureMgr.SetFeatureString(hash, value)
    end
end

local function get_combo_label(feature, values, default_value)
    if feature and feature.GetListIndex then
        local index = feature:GetListIndex()
        local value = values[(tonumber(index) or 0) + 1]
        if value and value ~= "" then return value end
    end

    return default_value or values[1] or ""
end

local function get_next_outfit_name()
    local preset = get_combo_label(outfit_name_preset_feature, OUTFIT_NAME_PRESETS, "Outfit")
    local number = outfit_name_number_feature and outfit_name_number_feature.GetIntValue and outfit_name_number_feature:GetIntValue() or 1
    number = clamp_int(number, 1, 999)
    return ("%s %d"):format(preset, number)
end

local function apply_next_outfit_name(show_message)
    local name = get_next_outfit_name()
    set_feature_string(outfit_name_feature, HASH_OUTFIT_NAME, name)
    if show_message then toast("Outfit name set to: " .. name) end
    return name
end

local function get_next_plate_text()
    local preset = get_combo_label(plate_preset_feature, PLATE_PRESETS, "MEOW")
    local number = plate_number_feature and plate_number_feature.GetIntValue and plate_number_feature:GetIntValue() or 1
    number = clamp_int(number, 0, 999)
    local suffix = ("%03d"):format(number)
    return (preset .. suffix):sub(1, 8)
end

local function apply_next_plate_text(show_message)
    local text = get_next_plate_text()
    plate_editor_text = text
    set_feature_string(plate_text_feature, HASH_PLATE_TEXT, text)
    set_feature_string(plate_text_2_feature, HASH_PLATE_TEXT_2, "")
    set_feature_string(plate_text_3_feature, HASH_PLATE_TEXT_3, "")
    if show_message then toast("Plate text set to: " .. text) end
    return text
end

local function normalize_plate_text(text)
    text = tostring(text or ""):upper():gsub("[^A-Z0-9 ]", "")
    return text:sub(1, 8)
end

local function sync_plate_editor_text(show_message)
    plate_editor_text = normalize_plate_text(plate_editor_text)
    set_feature_string(plate_text_feature, HASH_PLATE_TEXT, plate_editor_text)
    set_feature_string(plate_text_2_feature, HASH_PLATE_TEXT_2, "")
    set_feature_string(plate_text_3_feature, HASH_PLATE_TEXT_3, "")
    if show_message then toast("Custom plate: " .. (plate_editor_text ~= "" and plate_editor_text or "blank")) end
    return plate_editor_text
end

local function selected_plate_editor_position()
    local value = plate_editor_position_feature and plate_editor_position_feature.GetIntValue and plate_editor_position_feature:GetIntValue() or 1
    return clamp_int(value, 1, 8)
end

local function selected_plate_editor_char()
    local label = get_combo_label(plate_editor_char_feature, PLATE_CHARS, "A")
    if label == "Space" then return " " end
    return label:sub(1, 1)
end

local function set_plate_editor_char(show_message)
    local pos = selected_plate_editor_position()
    local char = selected_plate_editor_char()
    local text = normalize_plate_text(plate_editor_text)
    if #text < pos then
        text = text .. string.rep(" ", pos - #text)
    end
    plate_editor_text = text:sub(1, pos - 1) .. char .. text:sub(pos + 1)
    return sync_plate_editor_text(show_message)
end

local function plate_editor_backspace(show_message)
    local text = normalize_plate_text(plate_editor_text)
    plate_editor_text = text:sub(1, math.max(#text - 1, 0))
    return sync_plate_editor_text(show_message)
end

local function clear_plate_editor(show_message)
    plate_editor_text = ""
    return sync_plate_editor_text(show_message)
end

