local function set_ped_hair_tint(ped, color_id, highlight_color_id)
    color_id = clamp_int(color_id, 0, 63)
    highlight_color_id = clamp_int(highlight_color_id, 0, 63)
    if PED and PED.SET_PED_HAIR_TINT then
        PED.SET_PED_HAIR_TINT(ped, color_id, highlight_color_id)
        return true
    end
    return invoke_void(0x4CFFC65454C93A49, ped, color_id, highlight_color_id)
end

local function get_hair_color_values()
    local color = hair_color_feature and hair_color_feature.GetIntValue and hair_color_feature:GetIntValue() or 0
    local highlight = hair_highlight_feature and hair_highlight_feature.GetIntValue and hair_highlight_feature:GetIntValue() or color
    return clamp_int(color, 0, 63), clamp_int(highlight, 0, 63)
end

local function hair_override_is_enabled()
    return FeatureMgr
        and FeatureMgr.IsFeatureToggled
        and FeatureMgr.IsFeatureToggled(HASH_HAIR_OVERRIDE) == true
end

local function apply_hair_color_now(show_message)
    local ped = local_ped()
    if not entity_exists(ped) then
        if show_message then toast("Could not find your ped.") end
        return false
    end

    local color, highlight = get_hair_color_values()
    if set_ped_hair_tint(ped, color, highlight) then
        if show_message then toast("Hair color applied.") end
        return true
    end

    if show_message then toast("Could not apply hair color.") end
    return false
end

local function get_hair_slider_values(ped)
    local style = hair_style_feature and hair_style_feature:GetIntValue() or DEFAULT_HAIR_STYLE
    local style_count = get_ped_drawable_count(ped, HAIR_COMPONENT_ID) or 80
    local style_max = math.max(style_count - 1, 0)
    style = clamp_int(style, 0, style_max)

    local texture = hair_texture_feature and hair_texture_feature:GetIntValue() or DEFAULT_HAIR_TEXTURE
    local texture_count = get_ped_texture_count(ped, HAIR_COMPONENT_ID, style) or 16
    local texture_max = math.max(texture_count - 1, 0)
    texture = clamp_int(texture, 0, texture_max)

    if hair_style_feature and hair_style_feature.SetLimitValues then hair_style_feature:SetLimitValues(0, style_max) end
    if hair_texture_feature and hair_texture_feature.SetLimitValues then hair_texture_feature:SetLimitValues(0, texture_max) end

    return style, texture
end

local function apply_hair_override()
    local ped = local_ped()
    if not entity_exists(ped) then return false end

    local style, texture = get_hair_slider_values(ped)
    local ok = set_ped_component_variation(ped, HAIR_COMPONENT_ID, style, texture, 0)
    local color, highlight = get_hair_color_values()
    set_ped_hair_tint(ped, color, highlight)
    return ok
end

local function save_current_hair()
    local ped = local_ped()
    if not entity_exists(ped) then return false end

    saved_hair = {
        style = get_ped_drawable_variation(ped, HAIR_COMPONENT_ID) or 0,
        texture = get_ped_texture_variation(ped, HAIR_COMPONENT_ID) or 0,
        color = hair_color_feature and hair_color_feature.GetIntValue and hair_color_feature:GetIntValue() or DEFAULT_HAIR_COLOR,
        highlight = hair_highlight_feature and hair_highlight_feature.GetIntValue and hair_highlight_feature:GetIntValue() or DEFAULT_HAIR_HIGHLIGHT
    }
    return true
end

local function restore_saved_hair()
    saved_hair = nil
    return true
end

local function current_vehicle()
    local ped = local_ped()
    if not entity_exists(ped) then return 0 end

    if PED and PED.GET_VEHICLE_PED_IS_IN then
        local vehicle = PED.GET_VEHICLE_PED_IS_IN(ped, false)
        if vehicle and vehicle ~= 0 then return vehicle end
    end
    if VEHICLE and VEHICLE.GET_VEHICLE_PED_IS_IN then
        local vehicle = VEHICLE.GET_VEHICLE_PED_IS_IN(ped, false)
        if vehicle and vehicle ~= 0 then return vehicle end
    end
    return invoke_int(0x9A9112A0FE9A4713, ped, false) or 0
end

local function get_plate_text()
    local text = get_feature_string(plate_text_feature, HASH_PLATE_TEXT, "")
    local text_2 = get_feature_string(plate_text_2_feature, HASH_PLATE_TEXT_2, "")
    local text_3 = get_feature_string(plate_text_3_feature, HASH_PLATE_TEXT_3, "")
    text = tostring(text or ""):gsub("^%s+", ""):gsub("%s+$", "")
    text_2 = tostring(text_2 or ""):gsub("^%s+", ""):gsub("%s+$", "")
    text_3 = tostring(text_3 or ""):gsub("^%s+", ""):gsub("%s+$", "")
    if text == "" and plate_editor_text ~= "" then text = plate_editor_text end
    if text == "" or text == "MEOW" then text = get_next_plate_text() end
    if text_2 ~= "" then text = text .. " " .. text_2 end
    if text_3 ~= "" then text = text .. " " .. text_3 end
    if text == "" then text = "MEOW" end
    return text
end

local function get_plate_interval_ms()
    local value = plate_speed_feature and plate_speed_feature.GetIntValue and plate_speed_feature:GetIntValue() or DEFAULT_PLATE_INTERVAL_MS
    value = tonumber(value) or DEFAULT_PLATE_INTERVAL_MS
    value = math.floor(value)
    if value < 100 then return 100 end
    if value > 3000 then return 3000 end
    return value
end

local function set_vehicle_plate(vehicle, text)
    if not entity_exists(vehicle) then return false end
    text = tostring(text or ""):sub(1, 8)
    if VEHICLE and VEHICLE.SET_VEHICLE_NUMBER_PLATE_TEXT then
        VEHICLE.SET_VEHICLE_NUMBER_PLATE_TEXT(vehicle, text)
        return true
    end
    return invoke_void(0x95A88F0B409CDA47, vehicle, text)
end

local function set_current_plate(show_message)
    local vehicle = current_vehicle()
    if not entity_exists(vehicle) then
        if show_message then toast("Get in a vehicle first.") end
        return false
    end
    if set_vehicle_plate(vehicle, get_plate_text()) then
        if show_message then toast("Plate text set.") end
        return true
    end
    if show_message then toast("Could not set plate text.") end
    return false
end

local function scrolling_plate_text()
    local text = get_plate_text()
    text = "        " .. text .. "        "
    if #text <= 8 then return text end
    if plate_scroll_index > (#text - 7) then plate_scroll_index = 1 end
    local visible = text:sub(plate_scroll_index, plate_scroll_index + 7)
    plate_scroll_index = plate_scroll_index + 1
    return visible
end

local function update_scrolling_plate()
    local vehicle = current_vehicle()
    if not entity_exists(vehicle) then return false end
    return set_vehicle_plate(vehicle, scrolling_plate_text())
end

local function get_script_folder()
    if _G and _G.MeowPartyDataDir and _G.MeowPartyDataDir ~= "" then return _G.MeowPartyDataDir end
    if _G and _G.MeowPartyStorageDir and _G.MeowPartyStorageDir ~= "" then return _G.MeowPartyStorageDir end

    local source = debug and debug.getinfo and debug.getinfo(1, "S").source
    if source and source:sub(1, 1) == "@" then
        local folder = source:sub(2):match("^(.*[\\/])")
        if folder and folder ~= "" then return folder end
    end

    if FileMgr and FileMgr.GetMenuRootPath then
        local root = FileMgr.GetMenuRootPath()
        if root and root ~= "" then
            local sep = root:sub(-1)
            if sep ~= "\\" and sep ~= "/" then root = root .. "\\" end
            return root .. "Lua\\"
        end
    end

    local folders = {}
    local one_drive = os and os.getenv and (os.getenv("OneDrive") or os.getenv("OneDriveConsumer"))
    local user_profile = os and os.getenv and os.getenv("USERPROFILE")

    if one_drive and one_drive ~= "" then
        folders[#folders + 1] = one_drive .. "\\Documentos\\Cherax\\Lua\\"
        folders[#folders + 1] = one_drive .. "\\Documents\\Cherax\\Lua\\"
    end
    if user_profile and user_profile ~= "" then
        folders[#folders + 1] = user_profile .. "\\OneDrive\\Documentos\\Cherax\\Lua\\"
        folders[#folders + 1] = user_profile .. "\\OneDrive\\Documents\\Cherax\\Lua\\"
        folders[#folders + 1] = user_profile .. "\\Documentos\\Cherax\\Lua\\"
        folders[#folders + 1] = user_profile .. "\\Documents\\Cherax\\Lua\\"
    end

    for _, folder in ipairs(folders) do
        local test_path = folder .. "CleanMeowBlood.lua"
        if FileMgr and FileMgr.DoesFileExist then
            local exists = FileMgr.DoesFileExist(test_path)
            if exists then return folder end
        end
        if io and io.open then
            local file = io.open(test_path, "r")
            if file then
                file:close()
                return folder
            end
        end
    end

    return ""
end

local OUTFITS_FILE = get_script_folder() .. "CleanMeowOutfits.json"

local function read_text_file(path)
    if FileMgr and FileMgr.ReadFileContent then
        local content = FileMgr.ReadFileContent(path)
        if content and content ~= "" then return content end
    end
    if io and io.open then
        local file = io.open(path, "r")
        if file then
            local content = file:read("*a")
            file:close()
            return content
        end
    end
    return nil
end

local function write_text_file(path, content)
    if FileMgr and FileMgr.CreateDir then
        local folder = tostring(path or ""):match("^(.*[\\/])")
        if folder and folder ~= "" then FileMgr.CreateDir(folder) end
    end

    if FileMgr and FileMgr.WriteFileContent then
        local result = FileMgr.WriteFileContent(path, content or "", false)
        if result ~= false then return true end
    end
    if io and io.open then
        local file = io.open(path, "w")
        if file then
            file:write(content or "")
            file:close()
            return true
        end
    end
    return false
end


local function json_escape(value)
    value = tostring(value or "")
    value = value:gsub("\\", "\\\\")
    value = value:gsub("\"", "\\\"")
    value = value:gsub("\r", "\\r")
    value = value:gsub("\n", "\\n")
    return value
end

local function json_parse(text)
    if type(text) ~= "string" or text == "" then return nil end
    local pos = 1

    local function skip_ws()
        while true do
            local c = text:sub(pos, pos)
            if c == " " or c == "\n" or c == "\r" or c == "\t" then pos = pos + 1 else return end
        end
    end

    local function parse_string()
        if text:sub(pos, pos) ~= "\"" then return nil end
        pos = pos + 1
        local out = {}
        while pos <= #text do
            local c = text:sub(pos, pos)
            if c == "\"" then
                pos = pos + 1
                return table.concat(out)
            end
            if c == "\\" then
                local n = text:sub(pos + 1, pos + 1)
                if n == "n" then out[#out + 1] = "\n"
                elseif n == "r" then out[#out + 1] = "\r"
                elseif n == "t" then out[#out + 1] = "\t"
                else out[#out + 1] = n end
                pos = pos + 2
            else
                out[#out + 1] = c
                pos = pos + 1
            end
        end
        return nil
    end

    local parse_value

    local function parse_array()
        pos = pos + 1
        local arr = {}
        skip_ws()
        if text:sub(pos, pos) == "]" then pos = pos + 1 return arr end
        while pos <= #text do
            arr[#arr + 1] = parse_value()
            skip_ws()
            local c = text:sub(pos, pos)
            if c == "]" then pos = pos + 1 return arr end
            if c ~= "," then return nil end
            pos = pos + 1
        end
        return nil
    end

    local function parse_object()
        pos = pos + 1
        local obj = {}
        skip_ws()
        if text:sub(pos, pos) == "}" then pos = pos + 1 return obj end
        while pos <= #text do
            skip_ws()
            local key = parse_string()
            if key == nil then return nil end
            skip_ws()
            if text:sub(pos, pos) ~= ":" then return nil end
            pos = pos + 1
            obj[key] = parse_value()
            skip_ws()
            local c = text:sub(pos, pos)
            if c == "}" then pos = pos + 1 return obj end
            if c ~= "," then return nil end
            pos = pos + 1
        end
        return nil
    end

    parse_value = function()
        skip_ws()
        local c = text:sub(pos, pos)
        if c == "\"" then return parse_string() end
        if c == "{" then return parse_object() end
        if c == "[" then return parse_array() end
        local literal = text:sub(pos)
        if literal:sub(1, 4) == "true" then pos = pos + 4 return true end
        if literal:sub(1, 5) == "false" then pos = pos + 5 return false end
        if literal:sub(1, 4) == "null" then pos = pos + 4 return nil end
        local number_start, number_end = text:find("-?%d+%.?%d*", pos)
        if number_start == pos then
            local number_text = text:sub(number_start, number_end)
            pos = pos + #number_text
            return tonumber(number_text)
        end
        return nil
    end

    return parse_value()
end

local function encode_number_array(values)
    local parts = {}
    for i, value in ipairs(values or {}) do parts[i] = tostring(tonumber(value) or 0) end
    return "[" .. table.concat(parts, ",") .. "]"
end

local function encode_outfits(store)
    local lines = { "{", "  \"outfits\": [" }
    local outfits = store and store.outfits or {}
    for i, outfit in ipairs(outfits) do
        lines[#lines + 1] = "    {"
        lines[#lines + 1] = "      \"name\": \"" .. json_escape(outfit.name) .. "\","
        lines[#lines + 1] = "      \"source\": \"" .. json_escape(outfit.source) .. "\","
        lines[#lines + 1] = "      \"sourcePlayerId\": " .. tostring(tonumber(outfit.sourcePlayerId) or -1) .. ","
        lines[#lines + 1] = "      \"model\": " .. tostring(tonumber(outfit.model) or 0) .. ","
        lines[#lines + 1] = "      \"components\": ["
        for j, comp in ipairs(outfit.components or {}) do
            lines[#lines + 1] = "        " .. encode_number_array(comp) .. (j < #(outfit.components or {}) and "," or "")
        end
        lines[#lines + 1] = "      ],"
        lines[#lines + 1] = "      \"props\": ["
        for j, prop in ipairs(outfit.props or {}) do
            lines[#lines + 1] = "        " .. encode_number_array(prop) .. (j < #(outfit.props or {}) and "," or "")
        end
        lines[#lines + 1] = "      ],"
        lines[#lines + 1] = "      \"face\": {"
        lines[#lines + 1] = "        \"blend\": " .. encode_number_array(outfit.face and outfit.face.blend or {}) .. ","
        lines[#lines + 1] = "        \"eyeColor\": " .. tostring(tonumber(outfit.face and outfit.face.eyeColor) or -1) .. ","
        lines[#lines + 1] = "        \"hairTint\": " .. encode_number_array(outfit.face and outfit.face.hairTint or {}) .. ","
        lines[#lines + 1] = "        \"overlays\": ["
        local overlays = outfit.face and outfit.face.overlays or {}
        for j, overlay in ipairs(overlays) do
            lines[#lines + 1] = "          " .. encode_number_array(overlay) .. (j < #overlays and "," or "")
        end
        lines[#lines + 1] = "        ]"
        lines[#lines + 1] = "      }"
        lines[#lines + 1] = "    }" .. (i < #outfits and "," or "")
    end
    lines[#lines + 1] = "  ]"
    lines[#lines + 1] = "}"
    return table.concat(lines, "\n")
end

local function load_outfits()
    local parsed = json_parse(read_text_file(OUTFITS_FILE) or "")
    if type(parsed) == "table" and type(parsed.outfits) == "table" then
        outfits_cache = parsed
    else
        outfits_cache = { outfits = {} }
    end
    return outfits_cache
end

local function save_outfits()
    if write_text_file(OUTFITS_FILE, encode_outfits(outfits_cache)) then return true end
    toast("Could not save outfit JSON.")
    return false
end

local function ensure_outfit_file()
    local content = read_text_file(OUTFITS_FILE)
    if content and content ~= "" then return true end
    outfits_cache = { outfits = {} }
    return write_text_file(OUTFITS_FILE, encode_outfits(outfits_cache))
end

local function get_outfit_name(default_name)
    local name = get_feature_string(outfit_name_feature, HASH_OUTFIT_NAME, "")
    name = tostring(name or ""):gsub("^%s+", ""):gsub("%s+$", "")
    if name == "" or name == "Saved Outfit" then name = get_next_outfit_name() end
    if name == "" then name = default_name or "Saved Outfit" end
    return name
end

local function refresh_outfit_list()
    load_outfits()
    if not outfit_list_feature then return end

    local names = {}
    for _, outfit in ipairs(outfits_cache.outfits or {}) do
        local label = tostring(outfit.name or "Unnamed Outfit")
        if outfit.source and outfit.source ~= "" then label = label .. " [" .. tostring(outfit.source) .. "]" end
        names[#names + 1] = label
    end
    if #names == 0 then names[1] = "No saved outfits" end

    meow_outfit_list_refreshing = true
    if outfit_list_feature.SetList then outfit_list_feature:SetList(names) end
    if outfit_list_feature.SetListIndex then outfit_list_feature:SetListIndex(0) end
    meow_outfit_list_refreshing = false
end

local function get_selected_outfit_name()
    load_outfits()
    if outfit_list_feature and outfit_list_feature.GetListIndex then
        local index = outfit_list_feature:GetListIndex()
        local outfit = outfits_cache.outfits and outfits_cache.outfits[index + 1]
        if outfit and outfit.name then return outfit.name end
    end
    return get_outfit_name("Saved Outfit")
end

local function get_selected_outfit()
    load_outfits()
    if outfit_list_feature and outfit_list_feature.GetListIndex then
        local index = outfit_list_feature:GetListIndex()
        local outfit = outfits_cache.outfits and outfits_cache.outfits[index + 1]
        if outfit then return outfit end
    end
    return nil
end

