local function get_ped_prop_texture_index(ped, prop_id)
    if PED and PED.GET_PED_PROP_TEXTURE_INDEX then
        local value = PED.GET_PED_PROP_TEXTURE_INDEX(ped, prop_id)
        if value ~= nil then return value end
    end
    return invoke_int(0xE131A28626F81AB2, ped, prop_id) or 0
end

local function set_ped_prop_index(ped, prop_id, drawable_id, texture_id)
    if PED and PED.SET_PED_PROP_INDEX then
        PED.SET_PED_PROP_INDEX(ped, prop_id, drawable_id, texture_id or 0, true)
        return true
    end
    return invoke_void(0x93376B65A266EB5F, ped, prop_id, drawable_id, texture_id or 0, true)
end

local function clear_ped_prop(ped, prop_id)
    if PED and PED.CLEAR_PED_PROP then
        PED.CLEAR_PED_PROP(ped, prop_id)
        return true
    end
    return invoke_void(0x0943E5B8E078E76E, ped, prop_id)
end

local function get_feature_int(feature, default_value)
    if feature and feature.GetIntValue then
        local value = feature:GetIntValue()
        if value ~= nil then return tonumber(value) or default_value end
    end

    return default_value
end

local function set_slider_limits(feature, min_value, max_value, value)
    if not feature then return end
    max_value = math.max(min_value, max_value)
    value = clamp_int(value, min_value, max_value)
    if feature.SetLimitValues then feature:SetLimitValues(min_value, max_value) end
    if feature.SetIntValue then feature:SetIntValue(value) end
end

local function selected_wardrobe_component_id()
    local index = wardrobe_component_feature and wardrobe_component_feature.GetListIndex and wardrobe_component_feature:GetListIndex() or 0
    return clamp_int(index, 0, #WARDROBE_COMPONENTS - 1)
end

local function selected_wardrobe_prop_id()
    local index = wardrobe_prop_feature and wardrobe_prop_feature.GetListIndex and wardrobe_prop_feature:GetListIndex() or 0
    return clamp_int(index, 0, #WARDROBE_PROPS - 1)
end

local function refresh_wardrobe_component_limits()
    local ped = local_ped()
    if not entity_exists(ped) then return false end

    local component_id = selected_wardrobe_component_id()
    local drawable = get_feature_int(wardrobe_drawable_feature, get_ped_drawable_variation(ped, component_id) or 0)
    local drawable_max = math.max((get_ped_drawable_count(ped, component_id) or 1) - 1, 0)
    drawable = clamp_int(drawable, 0, drawable_max)

    local texture_max = math.max((get_ped_texture_count(ped, component_id, drawable) or 1) - 1, 0)
    local texture = clamp_int(get_feature_int(wardrobe_texture_feature, get_ped_texture_variation(ped, component_id) or 0), 0, texture_max)

    set_slider_limits(wardrobe_drawable_feature, 0, drawable_max, drawable)
    set_slider_limits(wardrobe_texture_feature, 0, texture_max, texture)
    return true
end

local function read_current_wardrobe_component(show_message)
    local ped = local_ped()
    if not entity_exists(ped) then
        if show_message then toast("Could not find your ped.") end
        return false
    end

    local component_id = selected_wardrobe_component_id()
    local drawable = get_ped_drawable_variation(ped, component_id) or 0
    local texture = get_ped_texture_variation(ped, component_id) or 0
    local drawable_max = math.max((get_ped_drawable_count(ped, component_id) or 1) - 1, 0)
    local texture_max = math.max((get_ped_texture_count(ped, component_id, drawable) or 1) - 1, 0)
    set_slider_limits(wardrobe_drawable_feature, 0, drawable_max, drawable)
    set_slider_limits(wardrobe_texture_feature, 0, texture_max, texture)
    if show_message then toast("Current wardrobe component loaded.") end
    return true
end

local function apply_wardrobe_component(show_message)
    local ped = local_ped()
    if not entity_exists(ped) then
        if show_message then toast("Could not find your ped.") end
        return false
    end

    local component_id = selected_wardrobe_component_id()
    refresh_wardrobe_component_limits()
    local drawable = get_feature_int(wardrobe_drawable_feature, 0)
    local texture = get_feature_int(wardrobe_texture_feature, 0)
    if set_ped_component_variation(ped, component_id, drawable, texture, 0) then
        refresh_wardrobe_component_limits()
        if show_message then toast("Wardrobe component applied.") end
        return true
    end

    if show_message then toast("Could not apply wardrobe component.") end
    return false
end

local function read_current_wardrobe_prop(show_message)
    local ped = local_ped()
    if not entity_exists(ped) then
        if show_message then toast("Could not find your ped.") end
        return false
    end

    local prop_id = selected_wardrobe_prop_id()
    local drawable = get_ped_prop_index(ped, prop_id) or -1
    local texture = get_ped_prop_texture_index(ped, prop_id) or 0
    set_slider_limits(wardrobe_prop_drawable_feature, -1, 200, drawable)
    set_slider_limits(wardrobe_prop_texture_feature, 0, 50, texture)
    if show_message then toast("Current wardrobe prop loaded.") end
    return true
end

local function apply_wardrobe_prop(show_message)
    local ped = local_ped()
    if not entity_exists(ped) then
        if show_message then toast("Could not find your ped.") end
        return false
    end

    local prop_id = selected_wardrobe_prop_id()
    local drawable = get_feature_int(wardrobe_prop_drawable_feature, -1)
    local texture = get_feature_int(wardrobe_prop_texture_feature, 0)
    if drawable < 0 then
        if clear_ped_prop(ped, prop_id) then
            if show_message then toast("Wardrobe prop cleared.") end
            return true
        end
    elseif set_ped_prop_index(ped, prop_id, drawable, texture) then
        if show_message then toast("Wardrobe prop applied.") end
        return true
    end

    if show_message then toast("Could not apply wardrobe prop.") end
    return false
end

local function get_head_blend_data(ped)
    if not (Memory and Memory.Alloc and Memory.Free and Memory.ReadInt and Memory.ReadFloat) then return nil end

    local ptr = Memory.Alloc(80)
    if not ptr or ptr == 0 then return nil end
    if Memory.MemSet then Memory.MemSet(ptr, 0, 80) end

    local ok = false
    if PED and PED.GET_PED_HEAD_BLEND_DATA then
        ok = PED.GET_PED_HEAD_BLEND_DATA(ped, ptr) == true
    elseif Natives and Natives.InvokeBool then
        ok = Natives.InvokeBool(0x2746BD9D88C5C5D0, ped, ptr) == true
    end

    local data = nil
    if ok then
        data = {
            Memory.ReadInt(ptr + 0),
            Memory.ReadInt(ptr + 8),
            Memory.ReadInt(ptr + 16),
            Memory.ReadInt(ptr + 24),
            Memory.ReadInt(ptr + 32),
            Memory.ReadInt(ptr + 40),
            Memory.ReadFloat(ptr + 48),
            Memory.ReadFloat(ptr + 56),
            Memory.ReadFloat(ptr + 64),
            Memory.ReadByte and Memory.ReadByte(ptr + 72) or 0
        }
    end

    Memory.Free(ptr)
    return data
end

local function set_head_blend_data(ped, blend)
    if type(blend) ~= "table" or #blend < 9 then return false end
    local is_parent = (tonumber(blend[10]) or 0) ~= 0
    if PED and PED.SET_PED_HEAD_BLEND_DATA then
        PED.SET_PED_HEAD_BLEND_DATA(
            ped,
            tonumber(blend[1]) or 0,
            tonumber(blend[2]) or 0,
            tonumber(blend[3]) or 0,
            tonumber(blend[4]) or 0,
            tonumber(blend[5]) or 0,
            tonumber(blend[6]) or 0,
            tonumber(blend[7]) or 0.0,
            tonumber(blend[8]) or 0.0,
            tonumber(blend[9]) or 0.0,
            is_parent
        )
        return true
    end
    return invoke_void(
        0x9414E18B9434C2FE,
        ped,
        tonumber(blend[1]) or 0,
        tonumber(blend[2]) or 0,
        tonumber(blend[3]) or 0,
        tonumber(blend[4]) or 0,
        tonumber(blend[5]) or 0,
        tonumber(blend[6]) or 0,
        tonumber(blend[7]) or 0.0,
        tonumber(blend[8]) or 0.0,
        tonumber(blend[9]) or 0.0,
        is_parent
    )
end

local function get_eye_color(ped)
    if PED and PED.GET_HEAD_BLEND_EYE_COLOR then
        local value = PED.GET_HEAD_BLEND_EYE_COLOR(ped)
        if value ~= nil then return value end
    end
    return invoke_int(0x76BBA2CEE66D47E9, ped) or -1
end

local function set_eye_color(ped, color_id)
    color_id = tonumber(color_id) or -1
    if color_id < 0 then return false end
    if PED and PED.SET_HEAD_BLEND_EYE_COLOR then
        PED.SET_HEAD_BLEND_EYE_COLOR(ped, color_id)
        return true
    end
    return invoke_void(0x50B56988B170AFDF, ped, color_id)
end

local function get_head_overlay(ped, overlay_id)
    if PED and PED.GET_PED_HEAD_OVERLAY then
        local value = PED.GET_PED_HEAD_OVERLAY(ped, overlay_id)
        if value ~= nil then return value end
    end
    return invoke_int(0xA60EF3B6461A4D43, ped, overlay_id) or 255
end

local function set_head_overlay(ped, overlay_id, index)
    index = tonumber(index) or 255
    if PED and PED.SET_PED_HEAD_OVERLAY then
        PED.SET_PED_HEAD_OVERLAY(ped, overlay_id, index, 1.0)
        return true
    end
    return invoke_void(0x48F44967FA05CC1E, ped, overlay_id, index, 1.0)
end

local function capture_face(ped, include_slider_hair_tint)
    local face = {
        blend = get_head_blend_data(ped) or {},
        eyeColor = get_eye_color(ped),
        hairTint = include_slider_hair_tint and {
            hair_color_feature and hair_color_feature:GetIntValue() or 0,
            hair_highlight_feature and hair_highlight_feature:GetIntValue() or 0
        } or {},
        overlays = {}
    }
    for overlay_id = 0, 12 do
        face.overlays[#face.overlays + 1] = { overlay_id, get_head_overlay(ped, overlay_id) or 255 }
    end
    return face
end

local function apply_face(ped, face)
    if type(face) ~= "table" then return end
    if face.blend then set_head_blend_data(ped, face.blend) end
    if face.eyeColor then set_eye_color(ped, face.eyeColor) end
    if type(face.hairTint) == "table" and #face.hairTint >= 2 then
        set_ped_hair_tint(ped, tonumber(face.hairTint[1]) or 0, tonumber(face.hairTint[2]) or 0)
    end
    for _, overlay in ipairs(face.overlays or {}) do
        set_head_overlay(ped, tonumber(overlay[1]) or 0, tonumber(overlay[2]) or 255)
    end
end

local function player_ped(player_id)
    local ped = 0
    if Players and Players.GetCPed then
        ped = ped_handle(Players.GetCPed(player_id))
    end
    if ped == 0 and Players and Players.GetPed then
        ped = ped_handle(Players.GetPed(player_id))
    end
    if ped == 0 and GTA and GTA.GetLocalPlayerId and GTA.GetLocalPed then
        local local_id = GTA.GetLocalPlayerId()
        if local_id == player_id then ped = ped_handle(GTA.GetLocalPed()) end
    end
    return ped
end

local function selected_player_ped()
    if not (Utils and Utils.GetSelectedPlayer) then return 0, "selected player" end
    local player_id = Utils.GetSelectedPlayer()
    if player_id == nil or player_id < 0 then return 0, "selected player" end
    local name = "Player " .. tostring(player_id)
    if Players and Players.GetName then
        local player_name = Players.GetName(player_id)
        if player_name and player_name ~= "" then name = player_name end
    end
    return player_ped(player_id), name, player_id
end

local function capture_outfit(ped, source, include_slider_hair_tint)
    if not entity_exists(ped) then return nil end
    local outfit = {
        name = get_outfit_name(source),
        source = source or "Me",
        model = get_entity_model(ped),
        components = {},
        props = {},
        face = {}
    }
    for component_id = 0, 11 do
        outfit.components[#outfit.components + 1] = {
            component_id,
            get_ped_drawable_variation(ped, component_id) or 0,
            get_ped_texture_variation(ped, component_id) or 0,
            get_ped_palette_variation(ped, component_id) or 0
        }
    end
    for prop_id = 0, 7 do
        outfit.props[#outfit.props + 1] = {
            prop_id,
            get_ped_prop_index(ped, prop_id) or -1,
            get_ped_prop_texture_index(ped, prop_id) or 0
        }
    end
    outfit.face = capture_face(ped, include_slider_hair_tint == true)
    return outfit
end

local function upsert_outfit(outfit)
    load_outfits()
    local replaced = false
    for i, saved in ipairs(outfits_cache.outfits) do
        if saved.name == outfit.name and saved.source == outfit.source then
            outfits_cache.outfits[i] = outfit
            replaced = true
            break
        end
    end
    if not replaced then outfits_cache.outfits[#outfits_cache.outfits + 1] = outfit end
    return save_outfits()
end


local function find_outfit(name)
    load_outfits()
    for _, outfit in ipairs(outfits_cache.outfits or {}) do
        if outfit.name == name then return outfit end
    end
    return nil
end

local function save_my_outfit()
    local outfit = capture_outfit(local_ped(), "Me", hair_override_is_enabled())
    if not outfit then toast("Could not find your ped.") return false end
    if upsert_outfit(outfit) then
        refresh_outfit_list()
        toast("Saved outfit: " .. outfit.name)
        return true
    end
    return false
end

local function save_selected_outfit()
    local ped, name, player_id = selected_player_ped()
    local outfit = capture_outfit(ped, name, true)
    if not outfit then toast("Selected player's ped is not loaded.") return false end
    outfit.sourcePlayerId = player_id
    if upsert_outfit(outfit) then
        refresh_outfit_list()
        toast("Saved " .. name .. "'s outfit as: " .. outfit.name)
        return true
    end
    return false
end

local function apply_outfit(outfit)
    local ped = local_ped()
    if not entity_exists(ped) then toast("Could not find your ped.") return false end

    if FeatureMgr and FeatureMgr.IsFeatureToggled
    and FeatureMgr.IsFeatureToggled(HASH_HAIR_OVERRIDE) then
        local override_feature = FeatureMgr.GetFeature and FeatureMgr.GetFeature(HASH_HAIR_OVERRIDE)
        if override_feature and override_feature.Toggle then
            override_feature:Toggle(false)
        end
    end

    local snapshot_key = tostring(outfit.name or "") .. "\31" .. tostring(outfit.source or "")
    local snapshot_ped = meow_character_snapshots[snapshot_key]
    if entity_exists(snapshot_ped) then
        invoke_void(0x148B08C2D2ACB884, snapshot_ped, ped, true)
        toast("Loaded full character: " .. tostring(outfit.name))
        return true
    end

    for _, comp in ipairs(outfit.components or {}) do
        set_ped_component_variation(ped, tonumber(comp[1]) or 0, tonumber(comp[2]) or 0, tonumber(comp[3]) or 0, tonumber(comp[4]) or 0)
    end
    for _, prop in ipairs(outfit.props or {}) do
        local prop_id = tonumber(prop[1]) or 0
        local drawable = tonumber(prop[2]) or -1
        if drawable < 0 then
            clear_ped_prop(ped, prop_id)
        else
            set_ped_prop_index(ped, prop_id, drawable, tonumber(prop[3]) or 0)
        end
    end

    if tostring(outfit.source or "") == "Me" then
        apply_face(ped, outfit.face)
    elseif type(outfit.face) == "table" then
        if outfit.face.blend then set_head_blend_data(ped, outfit.face.blend) end
        if outfit.face.eyeColor then set_eye_color(ped, outfit.face.eyeColor) end
        if type(outfit.face.hairTint) == "table" and #outfit.face.hairTint >= 2 then
            set_ped_hair_tint(
                ped,
                tonumber(outfit.face.hairTint[1]) or 0,
                tonumber(outfit.face.hairTint[2]) or 0
            )
        end
    end
    toast("Loaded outfit: " .. tostring(outfit.name))
    return true
end

local function load_named_outfit()
    local outfit = get_selected_outfit()
    local name = outfit and outfit.name or get_selected_outfit_name()
    if not outfit then outfit = find_outfit(name) end
    if not outfit then
        toast("No saved outfit named: " .. name)
        return false
    end
    return apply_outfit(outfit)
end

local function ensure_list_tab()
    if list_tab then return list_tab end
    if not (ListGUI and ListGUI.GetRootTab) then return nil end

    local root = ListGUI.GetRootTab()
    if not root then return nil end
    local self_tab = root.GetSubTab and root:GetSubTab("Self")
    if not self_tab and root.AddSubTab then self_tab = root:AddSubTab("Self", "Self") end
    if not self_tab then return nil end

    local existing = self_tab.GetSubTab and self_tab:GetSubTab(SCRIPT_NAME)
    if existing then
        list_tab = existing
    elseif self_tab.AddSubTab then
        list_tab = self_tab:AddSubTab(SCRIPT_NAME, SCRIPT_NAME)
    end

    _G.MeowAutoCleanListTab = list_tab
    return list_tab
end

local function add_to_list(hash)
    local tab = ensure_list_tab()
    if tab and tab.AddFeature then tab:AddFeature(hash) end
end

local function clean_now(show_message)
    local ped = local_ped()
    if not entity_exists(ped) then
        if show_message then toast("Could not find your ped.") end
        return false
    end

    clear_ped_damage(ped)

    if show_message then toast("Cleaned blood and bruises.") end
    return true
end

local function remove_feature(hash)
