copy_selected_character_feature = FeatureMgr.AddFeature(
    HASH_COPY_SELECTED_CHARACTER,
    "Copy Selected Player + Auto Save",
    eFeatureType.Button,
    "Copy the selected character and save it with the current outfit name.",
    function()
        local source_ped, source_name, source_player_id = selected_player_ped()
        local target_ped = local_ped()
        if not entity_exists(source_ped) then
            toast("Selected player's ped is not loaded.")
            return
        end
        if not entity_exists(target_ped) then
            toast("Could not find your ped.")
            return
        end

        if FeatureMgr and FeatureMgr.IsFeatureToggled
        and FeatureMgr.IsFeatureToggled(HASH_HAIR_OVERRIDE) then
            local override_feature = FeatureMgr.GetFeature and FeatureMgr.GetFeature(HASH_HAIR_OVERRIDE)
            if override_feature and override_feature.Toggle then
                override_feature:Toggle(false)
            end
        end

        local snapshot_ped = invoke_int(0xEF29A16337FACADB, source_ped, false, false, true)
        if entity_exists(snapshot_ped) then
            invoke_void(0xAD738C3085FE7E11, snapshot_ped, true, true)
            invoke_void(0xEA1C610A04DB6BBB, snapshot_ped, false, false)
            invoke_void(0x428CA6DBD1094446, snapshot_ped, true)
            invoke_void(0x1A9205C1B9EE827F, snapshot_ped, false, false)
        end

        invoke_void(0x148B08C2D2ACB884, source_ped, target_ped, true)
        local copied_outfit = capture_outfit(target_ped, source_name, true)
        if not copied_outfit then
            toast("Character copied, but the outfit could not be saved.")
            return
        end
        copied_outfit.sourcePlayerId = source_player_id
        if entity_exists(snapshot_ped) then
            local snapshot_key = tostring(copied_outfit.name or "") .. "\31" .. tostring(copied_outfit.source or "")
            local old_snapshot = meow_character_snapshots[snapshot_key]
            if entity_exists(old_snapshot) and old_snapshot ~= snapshot_ped and sink_entity then
                sink_entity(old_snapshot)
            end
            meow_character_snapshots[snapshot_key] = snapshot_ped
        end

        if upsert_outfit(copied_outfit) then
            refresh_outfit_list()
            toast("Copied and saved " .. tostring(source_name) .. " as: " .. tostring(copied_outfit.name))
        else
            toast("Character copied, but saving the outfit failed.")
        end
    end,
    true
)
if copy_selected_character_feature and copy_selected_character_feature.SetSearchable then
    copy_selected_character_feature:SetSearchable(true)
end
add_to_list(HASH_COPY_SELECTED_CHARACTER)

