function meow_party_settings_file()
    _G.MeowPartySettingsFile = get_script_folder() .. "settings.json"
    return _G.MeowPartySettingsFile
end

function meow_party_bool_text(value) return value and "true" or "false" end

function meow_party_settings_store()
    local parsed = json_parse(read_text_file(meow_party_settings_file()) or "")
    if type(parsed) ~= "table" then parsed = {} end
    if type(parsed.overlay) ~= "table" then parsed.overlay = {} end
    if type(parsed.plate) ~= "table" then parsed.plate = {} end
    return parsed
end

function meow_party_encode_settings(store)
    store = type(store) == "table" and store or {}
    store.overlay = type(store.overlay) == "table" and store.overlay or {}
    store.plate = type(store.plate) == "table" and store.plate or {}
    local overlay, plate = store.overlay, store.plate
    local lines = { "{", "  \"overlay\": {" }
    lines[#lines + 1] = "    \"enabled\": " .. meow_party_bool_text(overlay.enabled ~= false) .. ","
    lines[#lines + 1] = "    \"show_session_host\": " .. meow_party_bool_text(overlay.show_session_host ~= false) .. ","
    lines[#lines + 1] = "    \"show_script_host\": " .. meow_party_bool_text(overlay.show_script_host ~= false) .. ","
    lines[#lines + 1] = "    \"show_player_count\": " .. meow_party_bool_text(overlay.show_player_count ~= false) .. ","
    lines[#lines + 1] = "    \"drag_enabled\": " .. meow_party_bool_text(overlay.drag_enabled ~= false) .. ","
    lines[#lines + 1] = "    \"x\": " .. tostring(tonumber(overlay.x) or 88.0) .. ","
    lines[#lines + 1] = "    \"y\": " .. tostring(tonumber(overlay.y) or 48.0) .. ","
    lines[#lines + 1] = "    \"hex\": \"" .. json_escape(overlay.hex or "#991175") .. "\""
    lines[#lines + 1] = "  },"
    lines[#lines + 1] = "  \"plate\": {"
    lines[#lines + 1] = "    \"text\": \"" .. json_escape(plate.text or "MEOW") .. "\","
    lines[#lines + 1] = "    \"text2\": \"" .. json_escape(plate.text2 or "") .. "\","
    lines[#lines + 1] = "    \"text3\": \"" .. json_escape(plate.text3 or "") .. "\","
    lines[#lines + 1] = "    \"editorText\": \"" .. json_escape(plate.editorText or plate.text or "MEOW") .. "\","
    lines[#lines + 1] = "    \"position\": " .. tostring(tonumber(plate.position) or 1) .. ","
    lines[#lines + 1] = "    \"charIndex\": " .. tostring(tonumber(plate.charIndex) or 1) .. ","
    lines[#lines + 1] = "    \"speedMs\": " .. tostring(tonumber(plate.speedMs) or DEFAULT_PLATE_INTERVAL_MS) .. ","
    lines[#lines + 1] = "    \"scroll_enabled\": " .. meow_party_bool_text(plate.scroll_enabled ~= false)
    lines[#lines + 1] = "  }"
    lines[#lines + 1] = "}"
    return table.concat(lines, "\n")
end

function meow_party_overlay_toggle(id, fallback)
    if FeatureMgr and FeatureMgr.GetFeature and Utils and Utils.Joaat then
        local feature = FeatureMgr.GetFeature(Utils.Joaat("meow_host_overlay/" .. id))
        if feature and feature.IsToggled then return feature:IsToggled() end
    end
    return fallback ~= false
end

function meow_party_set_overlay_toggle(id, value)
    if FeatureMgr and FeatureMgr.GetFeature and Utils and Utils.Joaat then
        local feature = FeatureMgr.GetFeature(Utils.Joaat("meow_host_overlay/" .. id))
        if feature and feature.Toggle then
            value = value ~= false
            if not feature.IsToggled or feature:IsToggled() ~= value then feature:Toggle(value) end
        end
    end
end

function meow_party_collect_settings()
    local store = meow_party_settings_store()
    local overlay = rawget(_G, "meow_host_overlay")
    if type(overlay) == "table" then
        store.overlay.enabled = true
        store.overlay.show_session_host = meow_party_overlay_toggle("session", overlay.show_session_host)
        store.overlay.show_script_host = meow_party_overlay_toggle("script", overlay.show_script_host)
        store.overlay.show_player_count = meow_party_overlay_toggle("count", overlay.show_player_count)
        store.overlay.drag_enabled = meow_party_overlay_toggle("drag", overlay.drag_enabled)
        store.overlay.x = tonumber(overlay.x) or 88.0
        store.overlay.y = tonumber(overlay.y) or 48.0
        store.overlay.hex = tostring(overlay.hex or "#991175")
    end
    store.plate.text = get_feature_string(plate_text_feature, HASH_PLATE_TEXT, plate_editor_text or "MEOW")
    store.plate.text2 = get_feature_string(plate_text_2_feature, HASH_PLATE_TEXT_2, "")
    store.plate.text3 = get_feature_string(plate_text_3_feature, HASH_PLATE_TEXT_3, "")
    store.plate.editorText = normalize_plate_text(plate_editor_text or store.plate.text or "MEOW")
    store.plate.position = plate_editor_position_feature and plate_editor_position_feature.GetIntValue and plate_editor_position_feature:GetIntValue() or 1
    store.plate.charIndex = plate_editor_char_feature and plate_editor_char_feature.GetListIndex and (plate_editor_char_feature:GetListIndex() + 1) or 1
    store.plate.speedMs = plate_speed_feature and plate_speed_feature.GetIntValue and plate_speed_feature:GetIntValue() or DEFAULT_PLATE_INTERVAL_MS
    store.plate.scroll_enabled = scroll_plate_feature and scroll_plate_feature.IsToggled and scroll_plate_feature:IsToggled() or false
    return store
end

function meow_party_apply_overlay_settings(overlay)
    if type(overlay) ~= "table" then return end
    if type(_G.meow_host_overlay) ~= "table" then _G.meow_host_overlay = {} end
    _G.meow_host_overlay.enabled = true
    _G.meow_host_overlay.show_session_host = overlay.show_session_host ~= false
    _G.meow_host_overlay.show_script_host = overlay.show_script_host ~= false
    _G.meow_host_overlay.show_player_count = overlay.show_player_count ~= false
    _G.meow_host_overlay.drag_enabled = overlay.drag_enabled ~= false
    _G.meow_host_overlay.x = tonumber(overlay.x) or _G.meow_host_overlay.x or 88.0
    _G.meow_host_overlay.y = tonumber(overlay.y) or _G.meow_host_overlay.y or 48.0
    _G.meow_host_overlay.hex = tostring(overlay.hex or _G.meow_host_overlay.hex or "#991175")
    if _G.meow_host_overlay_apply_hex then _G.meow_host_overlay_apply_hex(_G.meow_host_overlay.hex, false) end
    if FeatureMgr and FeatureMgr.GetFeature and Utils and Utils.Joaat then
        local feature = FeatureMgr.GetFeature(Utils.Joaat("meow_host_overlay/hex_input"))
        if feature and feature.SetStringValue then feature:SetStringValue(_G.meow_host_overlay.hex) end
    end
    meow_party_set_overlay_toggle("show", true)
    meow_party_set_overlay_toggle("drag", _G.meow_host_overlay.drag_enabled)
    meow_party_set_overlay_toggle("session", _G.meow_host_overlay.show_session_host)
    meow_party_set_overlay_toggle("script", _G.meow_host_overlay.show_script_host)
    meow_party_set_overlay_toggle("count", _G.meow_host_overlay.show_player_count)
end

function meow_party_apply_plate_settings(plate)
    if type(plate) ~= "table" then return end
    plate_editor_text = normalize_plate_text(plate.editorText or plate.text or plate_editor_text or "MEOW")
    set_feature_string(plate_text_feature, HASH_PLATE_TEXT, plate.text or plate_editor_text)
    set_feature_string(plate_text_2_feature, HASH_PLATE_TEXT_2, plate.text2 or "")
    set_feature_string(plate_text_3_feature, HASH_PLATE_TEXT_3, plate.text3 or "")
    if plate_editor_position_feature and plate_editor_position_feature.SetIntValue then plate_editor_position_feature:SetIntValue(tonumber(plate.position) or 1) end
    if plate_editor_char_feature and plate_editor_char_feature.SetListIndex then plate_editor_char_feature:SetListIndex(math.max((tonumber(plate.charIndex) or 1) - 1, 0)) end
    if plate_speed_feature and plate_speed_feature.SetIntValue then plate_speed_feature:SetIntValue(tonumber(plate.speedMs) or DEFAULT_PLATE_INTERVAL_MS) end
    if scroll_plate_feature and scroll_plate_feature.Toggle then
        local scroll_on = plate.scroll_enabled ~= false
        if not scroll_plate_feature.IsToggled or scroll_plate_feature:IsToggled() ~= scroll_on then scroll_plate_feature:Toggle(scroll_on) end
    end
end

function meow_party_save_settings(show_message)
    if write_text_file(meow_party_settings_file(), meow_party_encode_settings(meow_party_collect_settings())) then
        if show_message then toast("Saved MeowParty settings.") end
        return true
    end
    if show_message then toast("Could not save MeowParty settings.") end
    return false
end

function meow_party_load_settings(show_message)
    local store = meow_party_settings_store()
    meow_party_apply_overlay_settings(store.overlay)
    meow_party_apply_plate_settings(store.plate)
    if show_message then toast("Loaded MeowParty settings.") end
    return true
end

meow_party_load_settings(false)
if not read_text_file(meow_party_settings_file()) then meow_party_save_settings(false) end

meow_party_save_settings_feature = FeatureMgr.AddFeature(Utils.Joaat("MeowPartySaveSettings"), "Save Settings", eFeatureType.Button, "Save overlay and license plate settings.", function() meow_party_save_settings(true) end, true)
