if meow_party_load_settings_feature then
    if meow_party_load_settings_feature.RegisterCallbackTrigger then meow_party_load_settings_feature:RegisterCallbackTrigger(eCallbackTrigger.OnClick) end
    if meow_party_load_settings_feature.SetSearchable then meow_party_load_settings_feature:SetSearchable(true) end
    add_to_list(Utils.Joaat("MeowPartyLoadSettings"))
end
