-- Integrated tools. Loud Radio uses Self; Outfit Lock joins Auto Clean/Bruises.
do
local function install_integrated_tools()
do
    local function int_toast(title, message)
        if GUI and GUI.AddToast then GUI.AddToast(title, message, 4000, eToastPos.TOP_RIGHT)
        elseif Logger and Logger.LogInfo then Logger.LogInfo("[" .. title .. "] " .. message) end
    end
    local function int_handle(value)
        if type(value) == "number" then return value end
        return GTA and GTA.PointerToHandle and (GTA.PointerToHandle(value) or 0) or 0
    end
    local function int_ped() return int_handle(GTA.GetLocalPed()) end
    local function int_exists(entity)
        return entity ~= 0 and Natives.InvokeBool(0x7239B21A38F536BA, entity)
    end
    local function int_add(path, id, name, kind, description, callback)
        local hash = Utils.Joaat("MeowParty/Integrated/" .. id)
        if FeatureMgr.RemoveFeature then FeatureMgr.RemoveFeature(hash) end
        local feature = FeatureMgr.AddFeature(hash, name, kind, description or "", callback, true)
        if feature.SetSaveable then feature:SetSaveable(false) end
        if feature.SetSearchable then feature:SetSearchable(true) end
        if feature.SetNoCallbackOnSettingsLoad then feature:SetNoCallbackOnSettingsLoad(true) end
        if path == "Auto Clean Blood/Bruises" then
            local tab = rawget(_G, "MeowAutoCleanListTab")
            if not tab then
                local root = ListGUI and ListGUI.GetRootTab and ListGUI.GetRootTab()
                local self_tab = root and root.GetSubTab and root:GetSubTab("Self")
                tab = self_tab and self_tab.GetSubTab and self_tab:GetSubTab(path)
            end
            if tab and tab.AddFeature then tab:AddFeature(hash) end
        else
            local tab = cherax_tab_for_path(path)
            if tab and tab.AddFeature then tab:AddFeature(hash) end
            local parts = cherax_menu_segments(path)
            cherax_ui_entries[#cherax_ui_entries + 1] = {
                hash = hash, name = name, label = path .. " / " .. name,
                category = "Self", main = "Self", group = parts[2] or "General",
                tab = parts[#parts] or "General",
            }
        end
        return feature
    end

    -- Loud Radio -------------------------------------------------------------
    local radio_objects, radio_station, radio_count = {}, 3, 1
    local radio_stations = {
        {"Los Santos Rock Radio","RADIO_01_CLASS_ROCK"},{"Non-Stop-Pop FM","RADIO_02_POP"},
        {"Radio Los Santos","RADIO_03_HIPHOP_NEW"},{"Channel X","RADIO_04_PUNK"},
        {"West Coast Talk Radio","RADIO_05_TALK_01"},{"Rebel Radio","RADIO_06_COUNTRY"},
        {"Soulwax FM","RADIO_07_DANCE_01"},{"East Los FM","RADIO_08_MEXICAN"},
        {"West Coast Classics","RADIO_09_HIPHOP_OLD"},{"The Blue Ark","RADIO_12_REGGAE"},
        {"Worldwide FM","RADIO_13_JAZZ"},{"FlyLo FM","RADIO_14_DANCE_02"},
        {"The Lowdown 9.11","RADIO_15_MOTOWN"},{"Radio Mirror Park","RADIO_16_SILVERLAKE"},
        {"Space 103.2","RADIO_17_FUNK"},{"Vinewood Boulevard Radio","RADIO_18_90S_ROCK"},
        {"Self Radio","RADIO_19_USER"},
        {"The Lab","RADIO_20_THELAB"},{"Blonded Los Santos","RADIO_21_DLC_XM17"},
        {"Los Santos Underground","RADIO_22_DLC_BATTLE_MIX1_RADIO"},
        {"iFruit Radio","RADIO_23_DLC_XM19_RADIO"},{"Still Slipping","RADIO_27_DLC_PRHEI4"},
        {"Kult FM","RADIO_34_DLC_HEI4_KULT"},{"The Music Locker","RADIO_35_DLC_HEI4_MLR"},
        {"Motomami","RADIO_37_MOTOMAMI"},
    }
    local function radio_model(hash)
        if not Natives.InvokeBool(0x35B9E0803292B641, hash)
            or not Natives.InvokeBool(0xC0296A2EDF545E92, hash) then return false end
        Natives.InvokeVoid(0x963D27A58DF860AC, hash)
        local started = os.clock()
        while not Natives.InvokeBool(0x98A4EB5D89A0C952, hash) do
            if os.clock() - started > 5 then return false end
            Script.Yield(0)
        end
        return true
    end
    local function radio_delete(entity)
        if not int_exists(entity) then return end
        for _ = 1, 20 do
            if Natives.InvokeBool(0x01BF60A500E28887, entity) then break end
            Natives.InvokeBool(0xB69317BF5E782347, entity); Script.Yield(0)
        end
        Natives.InvokeVoid(0xAD738C3085FE7E11, entity, true, true)
        local ptr = Memory.AllocInt(); Memory.WriteInt(ptr, entity)
        Natives.InvokeVoid(0xAE3CBE5BF394C9C9, ptr); Memory.Free(ptr)
    end
    local function radio_clear()
        for _, item in ipairs(radio_objects) do
            if int_exists(item.vehicle) then
                Natives.InvokeVoid(0xBB6F1CAEC68B0BCE, item.vehicle, false)
                Natives.InvokeVoid(0x1B9C0099CB942AC6, item.vehicle, "OFF")
            end
            radio_delete(item.driver); radio_delete(item.vehicle)
        end
        radio_objects = {}
    end
    local function radio_orphans()
        if not (PoolMgr and PoolMgr.GetMaxVehicleCount and PoolMgr.GetVehicle) then return end
        local ped, bus = int_ped(), Utils.Joaat("pbus2")
        for index = 0, PoolMgr.GetMaxVehicleCount() - 1 do
            local vehicle = PoolMgr.GetVehicle(index)
            if int_exists(vehicle) and Natives.InvokeInt(0x9F47B058362C84B5, vehicle) == bus
                and Natives.InvokeInt(0x48C2BED9180FE123, vehicle) == ped then
                radio_delete(Natives.InvokeInt(0xBB40DD2270B65366, vehicle, -1, false))
                radio_delete(vehicle)
            end
        end
    end
    local function radio_set_station()
        for _, item in ipairs(radio_objects) do
            if int_exists(item.vehicle) then
                Natives.InvokeVoid(0x1B9C0099CB942AC6, item.vehicle, radio_stations[radio_station][2])
            end
        end
    end
    local function radio_spawn()
        radio_clear()
        local bus, driver_model = Utils.Joaat("pbus2"), Utils.Joaat("a_m_y_skater_01")
        if not radio_model(bus) or not radio_model(driver_model) then
            int_toast("Loud Radio", "Could not load radio models."); return false
        end
        local ped = int_ped(); if ped == 0 then return false end
        local x, y, z = Natives.InvokeV3(0x3FEF770D40960D5A, ped, false)
        local heading = Natives.InvokeFloat(0xE83D4F9BA2A38914, ped)
        local bone = Natives.InvokeInt(0x3F428D08BE5AAE31, ped, 11816)
        for index = 1, radio_count do
            local spawn_z = z - 15.0 - index * 2.0
            local vehicle = int_handle(GTA.SpawnVehicle(bus, x, y, spawn_z, heading, true, true))
            local driver = int_handle(GTA.CreatePed(driver_model, 26, x, y, spawn_z, heading, true, true))
            if vehicle ~= 0 and driver ~= 0 then
                Natives.InvokeVoid(0xAD738C3085FE7E11, vehicle, true, true)
                Natives.InvokeVoid(0xAD738C3085FE7E11, driver, true, true)
                Natives.InvokeVoid(0x3882114BDE571AD4, vehicle, true)
                Natives.InvokeVoid(0x3882114BDE571AD4, driver, true)
                Natives.InvokeVoid(0x1A9205C1B9EE827F, vehicle, false, false)
                Natives.InvokeVoid(0x1A9205C1B9EE827F, driver, false, false)
                Natives.InvokeVoid(0xF75B0D629E1C063D, driver, vehicle, -1)
                Natives.InvokeVoid(0x1913FE4CBF41C463, driver, 32, false)
                Natives.InvokeVoid(0x9F8AA94D6D97DBF2, driver, true)
                Natives.InvokeVoid(0x2497C4717C8B881E, vehicle, true, true, false)
                Natives.InvokeVoid(0xB8FBC8B1330CA9B4, vehicle, true)
                Natives.InvokeVoid(0x3B988190C0AA6C0B, vehicle, true)
                Natives.InvokeVoid(0xBB6F1CAEC68B0BCE, vehicle, true)
                Natives.InvokeVoid(0x1B9C0099CB942AC6, vehicle, radio_stations[radio_station][2])
                Natives.InvokeVoid(0x6B9BBD38AB0796DF, vehicle, ped, bone, 0.0, 0.0,
                    -2.0 - (index - 1) * 0.05, 0.0, 0.0, 0.0,
                    false, false, false, false, 2, true, 0)
                Natives.InvokeVoid(0xEA1C610A04DB6BBB, vehicle, false, 0)
                Natives.InvokeVoid(0xEA1C610A04DB6BBB, driver, false, 0)
                radio_objects[#radio_objects + 1] = {vehicle = vehicle, driver = driver}
            else radio_delete(vehicle); radio_delete(driver) end
            Script.Yield(10)
        end
        int_toast("Loud Radio", "Enabled with " .. #radio_objects .. " hidden bus(es).")
        return #radio_objects > 0
    end
    local station_names = {}; for i, item in ipairs(radio_stations) do station_names[i] = item[1] end
    local station_feature = int_add("Self / Loud Radio", "Radio/Station", "Radio Station",
        eFeatureType.Combo, "Choose the station.", function(feature)
            radio_station = feature:GetListIndex() + 1; radio_set_station()
        end)
    station_feature:SetList(station_names); station_feature:SetListIndex(radio_station - 1)
    station_feature:RegisterCallbackTrigger(eCallbackTrigger.OnClick)
    local count_feature = int_add("Self / Loud Radio", "Radio/Count", "Volume (Bus Count)",
        eFeatureType.SliderInt, "More buses are louder; high values may lag.",
        function(feature) radio_count = feature:GetIntValue() end)
    count_feature:SetLimitValues(1, 10); count_feature:SetIntValue(1)
    count_feature:RegisterCallbackTrigger(eCallbackTrigger.OnClick)
    local radio_toggle = int_add("Self / Loud Radio", "Radio/Enabled", "Loud Radio",
        eFeatureType.Toggle, "Attach invisible buses that play your station.", function(feature)
            if feature:IsToggled() then if not radio_spawn() then feature:Toggle(false) end
            else radio_clear() end
        end)
    radio_toggle:RegisterCallbackTrigger(eCallbackTrigger.OnClick)
    local cleanup = int_add("Self / Loud Radio", "Radio/Cleanup", "Clean Up Loud Radio",
        eFeatureType.Button, "Remove current and leftover radio buses.", function()
            radio_clear(); radio_orphans()
            if radio_toggle:IsToggled() then radio_toggle:Toggle(false) end
            int_toast("Loud Radio", "Radio objects cleaned up.")
        end)
    cleanup:RegisterCallbackTrigger(eCallbackTrigger.OnClick)
    Script.RegisterLooped(function()
        for _, item in ipairs(radio_objects) do
            for _, entity in ipairs({item.vehicle, item.driver}) do
                if int_exists(entity) then
                    Natives.InvokeVoid(0xEA1C610A04DB6BBB, entity, false, 0)
                    Natives.InvokeVoid(0x44A0870B7E92D7C0, entity, 0, false)
                    Natives.InvokeVoid(0xE135A9FF3F5D05D8, entity)
                    Natives.InvokeVoid(0x1A9205C1B9EE827F, entity, false, false)
                end
            end
        end
    end)
    radio_orphans()

    -- Outfit Lock ------------------------------------------------------------
    local saved_components, saved_props, saved_model = {}, {}, nil
    local lock_enabled, last_lock_check, slot_features = false, 0, {}
    local component_names = {
        [1]="Mask",[3]="Torso / Shirt Upper",[4]="Legs / Pants",[5]="Bag",[6]="Shoes",
        [7]="Accessories",[8]="Undershirt",[9]="Body Armor",[10]="Decals",[11]="Top / Jacket",
    }
    local prop_names = {[0]="Hat",[1]="Glasses",[2]="Ear Accessory",[6]="Watch",[7]="Bracelet"}
    local locked_components = {[1]=true,[3]=true,[4]=true,[5]=true,[6]=true,[7]=true,[8]=true,[9]=true,[10]=true,[11]=true}
    local locked_props = {[0]=true,[1]=true,[2]=true,[6]=true,[7]=true}
    local function save_lock_outfit()
        local ped = int_ped(); if not int_exists(ped) then return false end
        saved_components, saved_props = {}, {}
        saved_model = Natives.InvokeInt(0x9F47B058362C84B5, ped)
        for slot = 0, 11 do
            saved_components[slot] = {
                Natives.InvokeInt(0x67F3780DD425D4FC, ped, slot),
                Natives.InvokeInt(0x04A355E041E004E6, ped, slot),
                Natives.InvokeInt(0xE3DD5F2A84B42281, ped, slot),
            }
        end
        for slot = 0, 9 do
            saved_props[slot] = {
                Natives.InvokeInt(0x898CC20EA75BACD8, ped, slot),
                Natives.InvokeInt(0x1833BB10F04F1287, ped, slot),
            }
        end
        return true
    end
    local function apply_lock_outfit(show_message)
        local ped = int_ped()
        if not int_exists(ped) or next(saved_components) == nil then return false end
        if Natives.InvokeInt(0x9F47B058362C84B5, ped) ~= saved_model then
            if show_message then int_toast("Outfit Lock", "Player model changed; save again.") end
            return false
        end
        local changed = false
        for slot, saved in pairs(saved_components) do
            if locked_components[slot] then
                local d = Natives.InvokeInt(0x67F3780DD425D4FC, ped, slot)
                local t = Natives.InvokeInt(0x04A355E041E004E6, ped, slot)
                local p = Natives.InvokeInt(0xE3DD5F2A84B42281, ped, slot)
                if d ~= saved[1] or t ~= saved[2] or p ~= saved[3] then
                    Natives.InvokeVoid(0x262B14F48D29DE80, ped, slot, saved[1], saved[2], saved[3])
                    changed = true
                end
            end
        end
        for slot, saved in pairs(saved_props) do
            if locked_props[slot] then
                local d = Natives.InvokeInt(0x898CC20EA75BACD8, ped, slot)
                local t = Natives.InvokeInt(0x1833BB10F04F1287, ped, slot)
                if d ~= saved[1] or (d ~= -1 and t ~= saved[2]) then
                    if saved[1] == -1 then Natives.InvokeVoid(0x0943E5B8E078E76E, ped, slot)
                    else Natives.InvokeVoid(0x93376B65A266EB5F, ped, slot, saved[1], saved[2], true) end
                    changed = true
                end
            end
        end
        if show_message then
            int_toast("Outfit Lock", changed and "Saved outfit restored." or "Outfit already matches.")
        end
        return true
    end
    local save_feature = int_add("Auto Clean Blood/Bruises", "Outfit/Save", "Save Outfit for Lock",
        eFeatureType.Button, "Capture your current outfit for the lock.", function()
            if save_lock_outfit() then int_toast("Outfit Lock", "Current outfit saved.") end
        end)
    save_feature:RegisterCallbackTrigger(eCallbackTrigger.OnClick)
    local lock_feature = int_add("Auto Clean Blood/Bruises", "Outfit/Lock", "Lock Outfit",
        eFeatureType.Toggle, "Only restores slots that changed, preventing constant flashing.", function(feature)
            lock_enabled = feature:IsToggled()
            if lock_enabled and next(saved_components) == nil then save_lock_outfit() end
            local now = os.clock()
            if lock_enabled and now - last_lock_check >= 0.25 then
                apply_lock_outfit(false); last_lock_check = now
            end
        end)
    lock_feature:RegisterCallbackTrigger(eCallbackTrigger.OnClick)
    lock_feature:RegisterCallbackTrigger(eCallbackTrigger.OnTick)
    local restore_feature = int_add("Auto Clean Blood/Bruises", "Outfit/Restore", "Restore Locked Outfit Now",
        eFeatureType.Button, "Restore selected changed slots once.", function() apply_lock_outfit(true) end)
    restore_feature:RegisterCallbackTrigger(eCallbackTrigger.OnClick)
    local function set_all_slots(enabled)
        for slot in pairs(locked_components) do locked_components[slot] = enabled end
        for slot in pairs(locked_props) do locked_props[slot] = enabled end
        for _, feature in ipairs(slot_features) do
            if feature:IsToggled() ~= enabled then feature:Toggle(enabled) end
        end
    end
    local all_feature = int_add("Auto Clean Blood/Bruises", "Outfit/All", "Select All Lock Slots",
        eFeatureType.Button, "Enable every outfit lock slot.", function() set_all_slots(true) end)
    all_feature:RegisterCallbackTrigger(eCallbackTrigger.OnClick)
    local none_feature = int_add("Auto Clean Blood/Bruises", "Outfit/None", "Clear All Lock Slots",
        eFeatureType.Button, "Disable every outfit lock slot.", function() set_all_slots(false) end)
    none_feature:RegisterCallbackTrigger(eCallbackTrigger.OnClick)
    for _, slot in ipairs({1,3,4,5,6,7,8,9,10,11}) do
        local slot_id = slot
        local feature = int_add("Auto Clean Blood/Bruises", "Outfit/Component/" .. slot_id,
            "Lock " .. component_names[slot_id], eFeatureType.Toggle, "", function(item)
                locked_components[slot_id] = item:IsToggled()
            end)
        feature:RegisterCallbackTrigger(eCallbackTrigger.OnClick); feature:Toggle(true)
        slot_features[#slot_features + 1] = feature
    end
    for _, slot in ipairs({0,1,2,6,7}) do
        local slot_id = slot
        local feature = int_add("Auto Clean Blood/Bruises", "Outfit/Prop/" .. slot_id,
            "Lock " .. prop_names[slot_id], eFeatureType.Toggle, "", function(item)
                locked_props[slot_id] = item:IsToggled()
            end)
        feature:RegisterCallbackTrigger(eCallbackTrigger.OnClick); feature:Toggle(true)
        slot_features[#slot_features + 1] = feature
    end
    cherax_ensure_tab()
end
end
install_integrated_tools()
end


if not meow_host_overlay_loaded then
    meow_host_overlay_loaded = true
    local function install_hud()
        local overlay = rawget(_G, "meow_host_overlay") or {
    enabled = true,
    show_session_host = true,
    show_script_host = true,
    show_player_count = true,
    drag_enabled = true,
    dragging = false,
    drag_offset_x = 0.0,
    drag_offset_y = 0.0,
    x = 88.0,
    y = 48.0,
    w = 280.0,
    h = 104.0,
    color = { r = 255, g = 0, b = 0, a = 255 },
    text = { r = 255, g = 245, b = 252, a = 255 },
    hex = "#991175"
}
_G.meow_host_overlay = overlay
overlay.enabled = overlay.enabled ~= false
overlay.show_session_host = overlay.show_session_host ~= false
overlay.show_script_host = overlay.show_script_host ~= false
overlay.show_player_count = overlay.show_player_count ~= false
overlay.drag_enabled = overlay.drag_enabled ~= false
overlay.x = tonumber(overlay.x) or 88.0
overlay.y = tonumber(overlay.y) or 48.0
overlay.w = tonumber(overlay.w) or 280.0
overlay.h = tonumber(overlay.h) or 104.0
overlay.color = overlay.color or { r = 255, g = 0, b = 0, a = 255 }
overlay.text = overlay.text or { r = 255, g = 245, b = 252, a = 255 }
overlay.hex = tostring(overlay.hex or "#991175")

local function safe_call(fn, ...)
    if type(fn) ~= "function" then return nil end
    return fn(...)
end

local function clamp(value, min_value, max_value)
    value = tonumber(value) or min_value
    if value < min_value then return min_value end
    if value > max_value then return max_value end
    return value
end

local function toast(message)
    if GUI and GUI.AddToast then
        GUI.AddToast("HUD", tostring(message or ""), 3500, eToastPos and eToastPos.TOP_RIGHT or 0)
    elseif cx_toast then
        cx_toast("HUD", tostring(message or ""))
    end
end

local function player_name(player_id)
    if player_id == nil or player_id < 0 then return "Unknown" end
    local name = safe_call(Players and Players.GetName, player_id)
    if name and name ~= "" then return tostring(name) end
    return "Player " .. tostring(player_id)
end

local function nint(hash, ...)
    if Natives and Natives.InvokeInt then return safe_call(Natives.InvokeInt, hash, ...) end
    return nil
end

local function player_count()
    local count = nint(0xA4A79DD2D9600654) or safe_call(NETWORK and NETWORK.NETWORK_GET_NUM_CONNECTED_PLAYERS)
    if type(count) == "number" and count > 0 then return count end
    count = 0
    for player_id = 0, 31 do
        if Players and Players.GetById and safe_call(Players.GetById, player_id) ~= nil then count = count + 1 end
    end
    return count
end

local function session_host()
    local host = nint(0x8251FB94DC4FDFC8) or safe_call(NETWORK and NETWORK.NETWORK_GET_HOST_PLAYER_INDEX)
    if type(host) ~= "number" or host < 0 then return "Unknown" end
    return player_name(host)
end

local function script_host()
    local host = nint(0x1D6A14F1F9A736FC, "freemode", -1, 0) or safe_call(NETWORK and NETWORK.NETWORK_GET_HOST_OF_SCRIPT, "freemode", -1, 0)
    if type(host) ~= "number" or host < 0 then host = nint(0xC7B4D79B01FA7A5C) or safe_call(NETWORK and NETWORK.NETWORK_GET_HOST_OF_THIS_SCRIPT) end
    if type(host) ~= "number" or host < 0 then return "Unknown" end
    return player_name(host)
end

local function nvoid(hash, ...)
    if Natives and Natives.InvokeVoid then Natives.InvokeVoid(hash, ...) end
end

local function hud_call(name, hash, ...)
    if HUD and type(HUD[name]) == "function" then return HUD[name](...) end
    return nvoid(hash, ...)
end

local function apply_hex(value, show_notice)
    local hex = tostring(value or overlay.hex or "")
    hex = hex:gsub("#", ""):gsub("0x", ""):gsub("%s+", "")
    if #hex == 3 then
        hex = hex:sub(1, 1) .. hex:sub(1, 1) .. hex:sub(2, 2) .. hex:sub(2, 2) .. hex:sub(3, 3) .. hex:sub(3, 3)
    end
    if not hex:match("^%x%x%x%x%x%x$") then
        if show_notice then toast("Use a color like #991175 or 00FFAA.") end
        return false
    end
    overlay.hex = "#" .. hex:upper()
    overlay.color.r = tonumber(hex:sub(1, 2), 16) or overlay.color.r
    overlay.color.g = tonumber(hex:sub(3, 4), 16) or overlay.color.g
    overlay.color.b = tonumber(hex:sub(5, 6), 16) or overlay.color.b
    overlay.color.a = 255
    if show_notice then toast("Color applied: " .. overlay.hex) end
    return true
end
_G.meow_host_overlay_apply_hex = apply_hex
apply_hex(overlay.hex, false)

local function draw_text(line, x, y, scale, color)
    color = color or overlay.color
    if not Natives and not HUD then return end
    hud_call("SET_TEXT_FONT", 0x66E0276CC5F6B9DA, 4)
    hud_call("SET_TEXT_SCALE", 0x07C837F9A01C34C9, 0.0, scale or 0.38)
    hud_call("SET_TEXT_COLOUR", 0xBE6B23FFA53FB442, color.r or 255, color.g or 0, color.b or 0, color.a or 255)
    hud_call("SET_TEXT_DROPSHADOW", 0x1CA3E9EAC9D93E5E, 1, 0, 0, 0, 180)
    hud_call("SET_TEXT_OUTLINE", 0x2513DFB0FB8400FE)
    hud_call("SET_TEXT_PROPORTIONAL", 0x038C1F517D7FDCF8, true)
    hud_call("SET_TEXT_CENTRE", 0xC02F4DBFB51D988B, false)
    hud_call("BEGIN_TEXT_COMMAND_DISPLAY_TEXT", 0x25FBB336DF1804CB, "STRING")
    hud_call("ADD_TEXT_COMPONENT_SUBSTRING_PLAYER_NAME", 0x6C188BE134E074AA, tostring(line or ""))
    hud_call("END_TEXT_COMMAND_DISPLAY_TEXT", 0xCD015E5BB0D96A57, x, y, 0)
end

local function apply_bounds()
    if not ImGui or not ImGui.GetDisplaySize then return end
    local sw, sh = safe_call(ImGui.GetDisplaySize)
    sw = tonumber(sw) or 1920.0
    sh = tonumber(sh) or 1080.0
    overlay.x = clamp(overlay.x, 0.0, math.max(0.0, sw - overlay.w))
    overlay.y = clamp(overlay.y, 0.0, math.max(0.0, sh - overlay.h))
end

local function mouse_pos()
    if not ImGui or not ImGui.GetMousePos then return nil, nil end
    local mx, my = safe_call(ImGui.GetMousePos)
    if type(mx) == "table" then return tonumber(mx.x or mx[1]), tonumber(mx.y or mx[2]) end
    return tonumber(mx), tonumber(my)
end

local function handle_drag()
    if not overlay.drag_enabled or not ImGui then return end
    local mx, my = mouse_pos()
    if not mx or not my then return end
    local over = mx >= overlay.x and mx <= overlay.x + overlay.w and my >= overlay.y and my <= overlay.y + 24.0
    local clicked = safe_call(ImGui.IsMouseClicked, 0)
    local down = safe_call(ImGui.IsMouseDown, 0)
    if over and clicked then
        overlay.dragging = true
        overlay.drag_offset_x = mx - overlay.x
        overlay.drag_offset_y = my - overlay.y
        safe_call(ImGui.CaptureMouseFromApp, true)
    end
    if overlay.dragging then
        if down then
            overlay.x = mx - overlay.drag_offset_x
            overlay.y = my - overlay.drag_offset_y
            apply_bounds()
            safe_call(ImGui.CaptureMouseFromApp, true)
        else
            overlay.dragging = false
            safe_call(ImGui.CaptureMouseFromApp, false)
        end
    end
end

function meow_host_overlay_draw()
    if not overlay.enabled then return end
    handle_drag()
    local x = (overlay.x or 88.0) / 1920.0
    local y = (overlay.y or 48.0) / 1080.0
    local gap = 0.032
    local line = 0
    if overlay.show_session_host then draw_text("Session Host: " .. session_host(), x, y + gap * line, 0.38, overlay.color); line = line + 1 end
    if overlay.show_script_host then draw_text("Script Host: " .. script_host(), x, y + gap * line, 0.38, overlay.color); line = line + 1 end
    if overlay.show_player_count then draw_text("Player Count: " .. tostring(player_count()) .. "/32", x, y + gap * line, 0.38, overlay.color) end
end

local function ensure_tab()
    if not ListGUI or not ListGUI.GetRootTab then return nil end
    local root_tab = safe_call(ListGUI.GetRootTab)
    if not root_tab then return nil end
    local script_tab = root_tab:GetSubTab("MeowEmotes") or root_tab:AddSubTab("MeowEmotes", "Meow party emotes")
    return script_tab:GetSubTab("HUD") or script_tab:AddSubTab("HUD", "HUD")
end

local function add_entry(hash, name, callback)
    if cherax_ui_entries then
        cherax_ui_entries[#cherax_ui_entries + 1] = {
            hash = hash,
            name = name,
            label = "HUD / " .. name,
            category = "HUD",
            main = "HUD",
            group = "Settings",
            tab = "Settings",
            callback = callback,
        }
    end
    if cherax_ensure_tab then cherax_ensure_tab() end
end

local function set_toggle(feature, value)
    if not feature or not feature.Toggle then return end
    value = value ~= false
    if feature.IsToggled and feature:IsToggled() == value then return end
    feature:Toggle(value)
end

local function add_feature(id, name, kind, desc, callback)
    if not FeatureMgr or not FeatureMgr.AddFeature then return nil end
    local hash = Utils and Utils.Joaat and Utils.Joaat("meow_host_overlay/" .. id) or id
    if FeatureMgr.RemoveFeature then FeatureMgr.RemoveFeature(hash) end
    local feature = FeatureMgr.AddFeature(hash, name, kind, desc or "", callback, true)
    if feature and kind == eFeatureType.InputText and feature.SetStringValue then feature:SetStringValue(tostring(overlay.hex or "#991175")) end
    if feature and feature.SetSearchable then feature:SetSearchable(true) end
    if feature and feature.SetSaveable then feature:SetSaveable(false) end
    if feature and feature.RegisterCallbackTrigger and eCallbackTrigger and eCallbackTrigger.OnClick then feature:RegisterCallbackTrigger(eCallbackTrigger.OnClick) end
    local tab = ensure_tab()
    if tab and tab.AddFeature then tab:AddFeature(hash) end
    add_entry(hash, name, function() if callback then callback(feature) end end)
    return feature
end

local show_feature = add_feature("show", "Show HUD", eFeatureType.Toggle, "Shows session host, script host, and player count.", function(feature)
